    moon:[{label:"혼자일 때의 진짜 모습",text:"새벽에 혼자 음악 들으면서 울거나, 아무것도 안 하면서 멍 때리거나, 별것 아닌 영화에서 감동받아서 한 시간 동안 생각함. 이 시간이 물고기자리의 진짜 충전 시간임."},{label:"감정 처리 방식",text:"감정을 있는 그대로 느낌. 분석 없이 그냥 느낌. 억지로 처리하려 하면 더 힘들어짐. 그냥 지나가게 두면 됨."},{label:"상처받을 때",text:"상처받으면 표현을 못 하고 혼자 삼킴. 이게 쌓이면 갑자기 연락이 끊기거나 멀어짐. 상대방은 '왜 갑자기?'라고 하지만 물고기자리는 이미 오래전부터 힘들었던 거임."}],
    rising:[{label:"남들이 보는 첫인상",text:"신비롭고 예술적인 느낌. 말이 적은데 분위기가 있음. '이 사람 뭔가 깊은 게 있을 것 같다'는 느낌을 줌. 사실 그냥 딴 생각 중이었지만 신비롭게 보임."},{label:"시간이 지나면",text:"현실 감각이 부족한 면이 드러남. 처음엔 '감성적인 사람'으로 보이던 게 나중엔 '좀 더 현실적이었으면'으로 느껴질 수 있음."},{label:"관계별 인상 차이",text:"처음 만난 사람에게는 '감성적이고 신비로운 사람', 오래 알고 지낸 사람에게는 '좋은데 가끔 이 사람이 어디 있는지 모르겠어', 연인에게는 '이렇게 나를 깊이 느끼는 사람이 있어?'."}],
    combo:"☀️🌙 세상을 아름답게 보는 외부 자아와 그 세상이 생각과 다를 때 상처받는 내부 자아. 물고기자리를 가장 감수성 풍부한 동시에 가장 상처받기 쉬운 사람으로 만듦.",
