/* ════════════════════════════════════════════════════════
   HELPERS
════════════════════════════════════════════════════════ */
function getSign(m,d){
  if((m===3&&d>=21)||(m===4&&d<=19)) return "aries";
  if((m===4&&d>=20)||(m===5&&d<=20)) return "taurus";
  if((m===5&&d>=21)||(m===6&&d<=20)) return "gemini";
  if((m===6&&d>=21)||(m===7&&d<=22)) return "cancer";
  if((m===7&&d>=23)||(m===8&&d<=22)) return "leo";
  if((m===8&&d>=23)||(m===9&&d<=22)) return "virgo";
  if((m===9&&d>=23)||(m===10&&d<=22)) return "libra";
  if((m===10&&d>=23)||(m===11&&d<=21)) return "scorpio";
  if((m===11&&d>=22)||(m===12&&d<=21)) return "sagittarius";
  if((m===12&&d>=22)||(m===1&&d<=19)) return "capricorn";
  if((m===1&&d>=20)||(m===2&&d<=18)) return "aquarius";
  return "pisces";
}
const isValidSignKey=(k)=>SIGNS.some(s=>s.key===k);
const decanOf=(deg)=>(deg==null||!Number.isFinite(deg))?null:(deg<10?1:deg<20?2:3);
const decanSignOf=(key,deg)=>{
  const dc=decanOf(deg); if(!dc) return null;
  const si=SIGNS.findIndex(s=>s.key===key); if(si<0) return null;
  return { decan:dc, sign:SIGNS[(si+4*(dc-1))%12] };
};

function buildAspects(real){
  if(!real) return [];
  const order=["sun","moon","mercury","venus","mars","jupiter","saturn"];
  const lons={};
  order.forEach((p)=>{
    const pl=real[p];
    if(!pl||!isValidSignKey(pl.key)||!Number.isFinite(Number(pl.deg))) return;
    lons[p]=SIGNS.findIndex(s=>s.key===pl.key)*30+Number(pl.deg);
  });
  const found=[];
  for(let i=0;i<order.length;i++){
    for(let j=i+1;j<order.length;j++){
      const a=order[i], b=order[j];
      if(!(a in lons)||!(b in lons)) continue;
      let sep=Math.abs(lons[a]-lons[b])%360;
      if(sep>180) sep=360-sep;
      ASPECT_DEFS.forEach((def)=>{
        const diff=Math.abs(sep-def.angle);
        if(diff<=def.orb) found.push({a,b,def,orb:Math.round(diff*10)/10,theme:PLANET_PAIR_THEMES[`${a}-${b}`]||""});
      });
    }
  }
  return found.sort((x,y)=>x.orb-y.orb).slice(0,5);
}

function buildBalance(planetList){
  const elems={fire:0,earth:0,air:0,water:0};
  const mods={cardinal:0,fixed:0,mutable:0};
  planetList.forEach((p)=>{ elems[p.elem]+=1; mods[modalityOf(p.key)]+=1; });
  const rank=(obj)=>Object.entries(obj).sort((a,b)=>b[1]-a[1]);
  const eRank=rank(elems), mRank=rank(mods);
  return {
    elems, mods, total:planetList.length,
    domElem:eRank[0][0], lackElem:eRank[eRank.length-1][0],
    domMod:mRank[0][0], lackMod:mRank[mRank.length-1][0],
  };
}

function calcPlacements(dateStr,timeStr,userName,sunKeyOverride,realPlacements){
  const d=new Date(dateStr), m=d.getMonth()+1, day=d.getDate(), y=d.getFullYear();
  const h=timeStr?parseInt(timeStr.split(":")[0]):12;
  const real=realPlacements&&typeof realPlacements==="object"?realPlacements:null;
  const realKey=(p)=>(real&&real[p]&&isValidSignKey(real[p].key))?real[p].key:null;
  const realDeg=(p)=>{
    const v=real&&real[p]?Number(real[p].deg):NaN;
    return Number.isFinite(v)?v:null;
  };
  const hasOverride = sunKeyOverride && isValidSignKey(sunKeyOverride);
  const sk=realKey("sun")||(hasOverride?sunKeyOverride:getSign(m,day)), si=SIGNS.findIndex(s=>s.key===sk);
  const mk=realKey("moon")||SIGNS[(si+(day%6)+2)%12].key;
  const rk=realKey("asc")||SIGNS[(si+(h%4)+1)%12].key;
  const vk=realKey("venus")||SIGNS[(si+2)%12].key;
  const mrk=realKey("mars")||SIGNS[(si+5)%12].key;
  const jupk=realKey("jupiter")||SIGNS[(si+3)%12].key;
  const satk=realKey("saturn")||SIGNS[(si+7)%12].key;
  const merk=realKey("mercury")||SIGNS[(si+1)%12].key;
  const make=(key,planet,god,emoji,pType,degSrc)=>({...SIGNS.find(s=>s.key===key),planet,god,emoji,pd:PD[key][pType],deg:degSrc?realDeg(degSrc):null});
  const futures=[
    `앞으로 3개월, ${SIGNS[si].name} 에너지가 최고조. 지금이 고백 타이밍. 망설이면 다음 기회는 목성 역행 이후 (약 8개월 후).`,
    `금성이 ${SIGNS[(si+2)%12].name} 위에 머무는 시기. 좋아하는 사람에게 먼저 연락하면 성공률 73%.`,
    `화성이 ${SIGNS[(si+5)%12].name}에서 순행 중. 하고 싶었던 거 지금 다 해. 번아웃 전까지는 무적.`,
    `달이 ${SIGNS[(si+(day%6)+2)%12].name} 그림자 아래. 감정을 숨기는 게 도움이 안 되는 시기.`,
  ];
  const jupElem=SIGNS.find(s=>s.key===jupk).elem;
  const satElem=SIGNS.find(s=>s.key===satk).elem;
  const merElem=SIGNS.find(s=>s.key===merk).elem;
  const sunElem=SIGNS[si].elem;
  const sun=make(sk,"태양","아폴론","☀️","sun","sun");
  const moon=make(mk,"달","아르테미스","🌙","moon","moon");
  const rising=make(rk,"상승궁","헤르메스","⬆️","rising","asc");
  const venus=make(vk,"금성","아프로디테","💘","venus","venus");
  const mars=make(mrk,"화성","아레스","🔥","mars","mars");
  const jupiter=make(jupk,"목성","제우스","⚡","sun","jupiter");
  const saturn=make(satk,"토성","크로노스","⏳","moon","saturn");
  const mercury=make(merk,"수성","헤르메스","🗣️","rising","mercury");
  const element=ELEMENTS[sunElem];
  const futureFlow=futures[(y+m+day)%4];
  const tazza={ style:TAZZA_STYLE[sunElem], luck:JUPITER_LUCK[jupElem], trap:SATURN_TRAP[satElem] };
  const premium=buildPremiumContent({
    name:userName||"당신",
    sun,
    moon,
    rising,
    venus,
    mars,
    jupiter,
    saturn,
    mercury,
    element,
    elemKey:sunElem,
    future:futureFlow,
    tazza,
    devil:DEVIL_MAP[sk],
  });
  const planetList=[sun,moon,rising,venus,mars,jupiter,saturn,mercury];
  return {
    sun,
    moon,
    rising,
    venus,
    mars,
    jupiter, jupElem,
    saturn, satElem,
    mercury, merElem,
    element, elemKey:sunElem,
    future:futureFlow,
    name:userName||"당신",
    daily:DAILY_ORACLES[sk][(day+y)%2],
    tazza,
    devil:DEVIL_MAP[sk],
    office:OFFICE_DATA[sk],
    atlas:buildDestinyAtlas({sun,moon,rising,elemKey:sunElem,birthDay:day,birthMonth:m}),
    fakbok:FAKBOK[sk],
    premium,
    sunKey:sk,
    birthDay:day, birthMonth:m, birthYear:y,
    calcMode:real?"swiss":"approx",
    risingApprox:!realKey("asc"),
    balance:buildBalance(planetList),
    aspects:buildAspects(real),
  };
}
function getCompat(ea,eb){
  return COMPAT_DB.find(c=>(c.a===ea&&c.b===eb)||(c.a===eb&&c.b===ea))||{title:"우주적 중립 관계",sub:"신들도 이 조합은 모름",score:60,detail:{synergy:"특별한 케미는 없지만 나쁜 것도 아님.",sun:"정보 없음.",moon:"정보 없음.",love:"그냥 사귀면 됨.",warning:"별자리 탓 금지."}};
}

function buildPremiumContent(ctx){
  const summary = [
    `${ctx.name}의 현재 차트는 ${ctx.sun.name} 태양의 방향성과 ${ctx.moon.name} 달의 정서 리듬, 그리고 ${ctx.rising.name} 상승궁의 현실 진입 방식이 뚜렷하게 분리되어 보이는 구조입니다. 겉에서 보이는 속도와 내면의 회복 속도가 다르기 때문에, 성과는 빠르게 내도 감정 회복은 의식적으로 챙겨야 안정적으로 오래 갑니다.`,
    `핵심 동력은 ${ctx.element.name} 원소에 기반합니다. 이 원소는 당신의 기본 반응, 스트레스 처리 방식, 관계에서 먼저 보여주는 태도를 결정하고, 오늘의 선택에서 "무엇을 지키고 무엇을 확장할지"를 가르는 기준점이 됩니다.`,
    `${ctx.jupiter.name} 목성은 기회가 어디서 열리는지, ${ctx.saturn.name} 토성은 어떤 패턴에서 손실이 나는지를 동시에 보여줍니다. 따라서 성장의 핵심은 무작정 확장이 아니라, 강한 구간에서는 과감하게 밀고 약한 구간에서는 규칙으로 손실을 차단하는 운영입니다.`,
    `연애와 인간관계에서는 ${ctx.venus.name} 금성이 끌림의 언어를, ${ctx.mars.name} 화성이 갈등과 추진의 언어를 담당합니다. 이 둘의 결이 맞는 사람과는 속도가 붙고, 결이 어긋나는 사람과는 사소한 대화에서도 에너지 누수가 커질 수 있습니다.`,
    `현재 흐름 신호는 다음과 같습니다. ${ctx.future} 이 문장은 단순 운세 문구가 아니라, 이번 사이클에서 어떤 행동은 바로 실행하고 어떤 행동은 타이밍을 분할해야 하는지 알려주는 운영 지침으로 읽는 것이 정확합니다.`
  ];

  const sunInterpretation = [
    `${ctx.sun.name} 태양은 당신이 결국 어떤 사람으로 남고 싶은지를 말합니다. 이 축은 단기 기분보다 장기 명분을 선택하게 만들며, 삶의 방향을 정할 때 "내가 자랑스러울 선택인가"를 먼저 묻는 성향으로 나타납니다.`,
    `반복적으로 끌리는 방향은 역할의 선명함입니다. 애매한 자리보다 책임이 분명한 자리에서 에너지가 살아나고, 목표가 뚜렷할수록 당신의 실행력과 몰입은 빠르게 올라갑니다.`,
    `성공할 때 드러나는 모습은 ${ctx.sun.god}의 상징과 닮아 있습니다. 존재감이 커지고 판단이 단순해지며, 주변은 당신을 "흔들리지 않는 기준점"으로 인식하기 시작합니다.`,
    `무너질 때의 그림자는 과도한 자기 몰입입니다. 방향을 잃는 순간 자신을 의심하거나, 반대로 확신 과잉으로 타인의 리듬을 놓칠 수 있습니다. 이때는 결정의 속도보다 결정의 근거를 복구하는 것이 먼저입니다.`,
    `태양궁을 현실에서 잘 쓰는 전략은 세 가지입니다. 큰 목표를 주간 단위 행동으로 쪼개고, 성과 지표를 외부 인정이 아닌 내부 기준으로 잡고, 관계에서는 주도권보다 합의의 속도를 관리해야 장기전에서 지치지 않습니다.`,
    `${ctx.sun.god}의 신탁 상징은 "방향의 불꽃"입니다. 당신은 누군가의 허락으로 움직이는 사람이 아니라, 스스로 방향을 점화할 때 가장 강해지는 타입입니다.`
  ];

  const moonInterpretation = [
    `${ctx.moon.name} 달궁은 당신의 감정이 움직이는 기본 알고리즘입니다. 생각보다 감정이 먼저 반응하고, 그 반응을 해석하는 과정에서 하루의 컨디션이 결정되는 경향이 분명합니다.`,
    `외로움을 느끼는 패턴은 "이해받지 못한다"는 감각에서 시작됩니다. 사람의 수가 적어서가 아니라, 감정의 결을 안전하게 말할 수 있는 공간이 없을 때 정서적 고립이 커집니다.`,
    `사랑받고 있다고 느끼는 조건은 화려한 이벤트보다 일관성입니다. 답장의 톤, 약속의 반복, 작은 배려의 누적 같은 미세한 신뢰 신호가 당신의 안정 회로를 여는 핵심 조건입니다.`,
    `불안할 때의 반응은 과해석 혹은 과회피로 갈리기 쉽습니다. 그래서 감정이 올라오는 날에는 결론을 미루고, 몸의 리듬을 먼저 회복하는 루틴이 필요합니다.`,
    `회복을 돕는 장소는 소음이 낮고 리듬이 일정한 곳입니다. 물길이 보이는 산책로, 시야가 열린 루프탑, 조용한 서가처럼 감정 압력을 분산시키는 공간이 특히 잘 맞습니다.`,
    `달궁이 추천 장소와 연결되는 이유는 단순 취향이 아니라 회복 메커니즘 때문입니다. 당신은 공간의 결에 따라 정서 복구 속도가 크게 달라지는 타입이며, 맞는 장소를 고르면 관계와 일의 품질까지 함께 올라갑니다.`
  ];

  const risingInterpretation = [
    `${ctx.rising.name} 상승궁은 사람들이 처음 체감하는 당신의 공기입니다. 첫인상에서 드러나는 말투, 속도, 표정의 질감이 기회의 문을 여는 방식까지 직접 연결됩니다.`,
    `세상에 적응하는 방식은 "먼저 판을 읽고 그다음 포지션을 잡는" 전략입니다. 즉흥처럼 보여도 실제로는 상대의 분위기와 규칙을 빠르게 스캔한 뒤 움직이는 편입니다.`,
    `기회를 잡는 첫 행동 패턴은 작은 신호를 놓치지 않는 민감성입니다. 짧은 대화, 미묘한 타이밍, 사소한 요청 안에서 다음 기회의 문장을 먼저 읽어내는 강점이 있습니다.`,
    `상승궁이 강해질 때는 대외운이 열립니다. 소개, 제안, 협업, 첫 만남에서 성과가 나고 당신의 전문성은 예상보다 빠르게 신뢰를 얻게 됩니다.`,
    `상승궁이 약해질 때의 오해는 "겉모습과 속마음의 불일치"입니다. 좋은 의도라도 전달 방식이 거칠거나 과장되면 당신의 진심이 왜곡되어 받아들여질 수 있습니다.`,
    `지금부터 강화할 외적 전략은 세 가지입니다. 첫 문장을 짧고 명확하게 시작하고, 약속의 마감 시간을 수치로 말하고, 첫인상 이후 24시간 내 후속 메시지로 신뢰를 고정하면 운의 문이 오래 열립니다.`
  ];

  const synthesis = [
    `당신의 태양은 ${ctx.sun.name}의 방식으로 삶의 방향을 밀어붙이고, 달은 ${ctx.moon.name}의 방식으로 안전과 정서적 확인을 원하며, 상승궁은 ${ctx.rising.name}의 방식으로 세상과 첫 접점을 만듭니다. 이 세 축은 서로 다른 언어를 쓰지만, 정렬되면 매우 강한 추진력을 만듭니다.`,
    `충돌은 대체로 "속도"에서 발생합니다. 태양은 장기 목표를 위해 전진하고 싶은데, 달은 감정 복구 시간을 요구하고, 상승궁은 외부 기대에 맞춰 즉각 반응하려 하기 때문에 내외부 리듬이 어긋날 수 있습니다.`,
    `조화를 이루는 핵심은 역할 분리입니다. 태양에게는 방향 결정을, 달에게는 회복 루틴을, 상승궁에게는 실행 커뮤니케이션을 맡기면 각각의 강점이 충돌하지 않고 연결됩니다.`,
    `운이 열릴 때의 징후는 분명합니다. 감정이 과열되지 않은 상태에서 빠른 실행이 가능해지고, 관계에서는 설명이 줄어도 오해가 줄어드는 흐름이 나타납니다. 이것이 세 축이 한 방향으로 정렬됐다는 신호입니다.`,
    `한 줄 신탁: "당신의 태양은 앞으로 가라고 명령하고, 달은 다치지 말라고 속삭이며, 상승궁은 웃으며 문을 여니, 지금 당신의 승부처는 속도가 아니라 리듬을 잃지 않는 전진입니다."`
  ];

  const places = buildPremiumPlaces(ctx);
  const tazzaGuide = buildPremiumTazzaGuide(ctx);
  const finalOracles = [
    `당신이 지금 걸어야 할 것은 과시가 아니라 반복 가능한 루틴입니다.`,
    `운은 큰 결심보다 작은 정렬에서 먼저 열린다는 사실을 잊지 마세요.`,
    `사람의 마음을 얻기 전에 먼저 내 리듬을 지키면 관계운이 오래갑니다.`,
    `이번 사이클의 승부처는 속공이 아니라, 손실을 줄인 정밀한 전진입니다.`,
    `${ctx.sun.god}의 문장은 단순합니다. 두려움을 없애려 하지 말고, 두려움과 함께 정확하게 움직이세요.`
  ];

  return { summary, sunInterpretation, moonInterpretation, risingInterpretation, synthesis, places, tazzaGuide, finalOracles };
}

function buildPremiumPlaces(ctx){
  const moonElem = ctx.moon.elem;
  const risingElem = ctx.rising.elem;
  const sunElem = ctx.elemKey;
  const catTargets = [
    "회복 장소",
    "집중 장소",
    "연애운이 열리는 장소",
    "금전운이 살아나는 장소",
    "영감이 오는 장소",
    "인간관계를 정리하기 좋은 장소",
    "새로운 시작에 좋은 장소",
    "혼자 가면 좋은 장소",
    "누군가와 함께 가면 좋은 장소",
    "피해야 할 장소",
  ];
  const base = [
    { name:"깊은 물빛이 보이는 강변 산책로", cats:["회복 장소","혼자 가면 좋은 장소"], elems:["water","air"], reasonCore:"흐르는 물을 눈에 담는 것만으로 과열된 생각이 가라앉는 공간입니다. 물의 리듬이 감정의 파고를 정돈해 주어, 결론이 안 나던 고민이 걷는 동안 저절로 정리됩니다.", actions:"혼자 걷기, 생각 정리, 음성 메모", luck:"감정 정리운과 관계 회복운", caution:"사람이 몰리는 주말 오후는 피하세요", avoidTime:"주말 오후" },
    { name:"시야가 열린 조용한 루프탑 카페", cats:["집중 장소","영감이 오는 장소"], elems:["air","fire"], reasonCore:"높은 시야는 공기 원소의 사고 회로를 여는 스위치입니다. 시선이 멀리 닿는 곳에서는 눈앞의 급한 일 대신 판 전체가 보이기 시작합니다.", actions:"계획 수립, 노트북 작업, 기획 메모", luck:"아이디어 실현운과 실행 타이밍운", caution:"카페인 과다로 리듬이 깨지지 않게 90분 단위로 쉬세요", avoidTime:"야간 피로 누적 시간" },
    { name:"햇빛이 오래 머무는 식물 온실", cats:["회복 장소","새로운 시작에 좋은 장소"], elems:["earth","fire"], reasonCore:"빛과 흙이 함께 있는 공간은 소모된 생기를 다시 채우는 재생의 자리입니다. 자라는 것들 곁에서는 몸의 회복 속도가 눈에 띄게 빨라집니다.", actions:"호흡 정리, 다음 달 목표 3개 작성", luck:"재생운과 건강 리셋운", caution:"한 번에 많은 결정을 하지 말고 1개만 확정하세요", avoidTime:"과열된 한낮" },
    { name:"작은 독립서점의 창가 좌석", cats:["집중 장소","영감이 오는 장소"], elems:["earth","air"], reasonCore:"낮은 소음과 일정한 밀도의 공간은 산만해진 수성 에너지를 한 점으로 모아 줍니다. 활자 곁에서는 생각이 문장으로 정리되는 속도가 빨라집니다.", actions:"자료 조사, 공부, 문장 정리", luck:"학습운과 문서 성과운", caution:"완벽주의로 오래 붙잡지 말고 2시간 타이머를 거세요", avoidTime:"폐점 직전" },
    { name:"로컬 재래시장 새벽 구간", cats:["금전운이 살아나는 장소","새로운 시작에 좋은 장소"], elems:["earth","fire"], reasonCore:"돈이 실제로 도는 현장은 흙 원소의 현실 감각을 깨우는 곳입니다. 관념적인 재테크 고민이 여기서는 구체적인 숫자와 감각으로 바뀝니다.", actions:"가격 감각 익히기, 현실 아이디어 수집", luck:"현금 흐름운과 사업 감각운", caution:"충동 지출 대신 예산 한도를 먼저 정하세요", avoidTime:"점심 이후 혼잡 시간" },
    { name:"공예 작업실이 모인 골목", cats:["영감이 오는 장소","누군가와 함께 가면 좋은 장소"], elems:["water","earth"], reasonCore:"손으로 만드는 사람들의 밀도가 높은 골목은 창작 감각을 전염시키는 공간입니다. 완성물이 아니라 과정을 구경하는 것만으로 막힌 영감이 풀립니다.", actions:"창작 시도, 취향 탐색, 협업 대화", luck:"창작운과 인연 연결운", caution:"비교 심리가 올라오면 기록만 하고 판단은 미루세요", avoidTime:"피곤한 저녁" },
    { name:"조용한 사찰길 혹은 오래된 성곽길", cats:["인간관계를 정리하기 좋은 장소","혼자 가면 좋은 장소"], elems:["earth","water"], reasonCore:"오래된 길은 시간의 축을 길게 늘여 주는 공간입니다. 수백 년 된 돌담 옆에서는 지금의 인간관계 고민이 제 크기로 보이고, 정리할 것과 지킬 것이 갈립니다.", actions:"관계 우선순위 정리, 미련 정리 노트", luck:"관계 정리운과 마음 안정운", caution:"죄책감으로 결정을 번복하지 않도록 기준을 미리 적어두세요", avoidTime:"폭우/강풍 시간" },
    { name:"아침 첫차 시간의 해변 산책로", cats:["새로운 시작에 좋은 장소","회복 장소"], elems:["water","fire"], reasonCore:"하루가 시작되기 전의 바다는 결심을 봉인하는 자리입니다. 수평선과 새 빛이 같이 있는 시간대는 '오늘부터'라는 말에 실제 무게를 실어 줍니다.", actions:"새 출발 선언, 짧은 러닝, 호흡", luck:"출발운과 결단력운", caution:"밤샘 후 방문은 피로를 키울 수 있습니다", avoidTime:"수면 부족한 날" },
    { name:"작은 재즈바의 오픈 직후 좌석", cats:["연애운이 열리는 장소","누군가와 함께 가면 좋은 장소"], elems:["water","air"], reasonCore:"음악이 대화의 속도를 늦춰 주는 공간입니다. 서두르지 않는 리듬 속에서는 금성의 언어 — 미묘한 호감 신호가 잘 들리고, 관계의 온도를 정확히 잴 수 있습니다.", actions:"깊은 대화, 관계 속도 조절", luck:"호감 신호 감지운과 관계 심화운", caution:"감정 과열 상태에서 중요한 약속은 보류하세요", avoidTime:"자정 이후" },
    { name:"도시 전망이 보이는 코워킹 라운지", cats:["금전운이 살아나는 장소","집중 장소"], elems:["air","earth"], reasonCore:"일하는 사람들의 밀도가 만드는 긴장감은 목성의 확장 에너지를 실무로 번역해 주는 환경입니다. 전망과 책상이 같이 있는 곳에서 제안서의 스케일이 커집니다.", actions:"제안서 작성, 예산 계획, 협업 미팅", luck:"수입 확장운과 협업 성과운", caution:"멀티태스킹 과부하를 막기 위해 1순위 작업만 먼저 진행하세요", avoidTime:"점심 직후 저집중 구간" },
    { name:"인파가 과밀한 소음형 쇼핑몰", cats:["피해야 할 장소"], elems:["fire"], reasonCore:"자극이 사방에서 쏟아지는 공간은 지금의 당신에게 판단력 누수 구간입니다. 소음과 인파는 불 원소의 충동 회로를 자극해 계획에 없던 소비와 결정을 부릅니다.", actions:"필요한 일만 빠르게 끝내고 이탈", luck:"불필요한 소모 차단운", caution:"자극 과부하로 판단이 흐려지기 쉬우니 체류 시간을 40분 이내로 제한하세요", avoidTime:"주말 피크타임" },
    { name:"의견이 충돌하기 쉬운 폐쇄형 모임 공간", cats:["피해야 할 장소","인간관계를 정리하기 좋은 장소"], elems:["air"], reasonCore:"출구 없는 방에서의 감정 토론은 수성의 말이 화성의 무기로 바뀌기 가장 쉬운 조건입니다. 지금 흐름에서는 말로 이겨도 관계에서 잃는 판이 됩니다.", actions:"감정 토론 대신 사실 확인만 진행", luck:"갈등 손실 최소화운", caution:"결론을 강요하면 오해가 커집니다. 기록 중심으로 짧게 끝내세요", avoidTime:"피로 누적 저녁" },
  ];

  const ranked = base.map((item, idx)=>{
    let score = 0;
    if (item.elems.includes(sunElem)) score += 3;
    if (item.elems.includes(moonElem)) score += 2;
    if (item.elems.includes(risingElem)) score += 2;
    if (item.cats.includes("피해야 할 장소")) score -= 3;
    score += (idx % 3);
    return { ...item, score };
  }).sort((a,b)=>b.score-a.score);

  const picks = [];
  catTargets.forEach((cat)=>{
    const found = ranked.find(r=>r.cats.includes(cat) && !picks.includes(r));
    if (found) picks.push(found);
  });
  ranked.forEach((r)=>{
    if (picks.length >= 10) return;
    if (!picks.includes(r)) picks.push(r);
  });

  return picks.slice(0, 10).map((p)=>{
    const matched=[];
    if (p.elems.includes(sunElem)) matched.push(`태양(${ctx.sun.name})의 ${ctx.element.name} 기질`);
    if (p.elems.includes(moonElem)) matched.push(`달(${ctx.moon.name})의 정서 리듬`);
    if (p.elems.includes(risingElem)) matched.push(`상승궁(${ctx.rising.name})의 대외 리듬`);
    const isAvoid=p.cats[0]==="피해야 할 장소";
    const matchLine=isAvoid
      ? "당신의 현재 배치에서는 이곳의 자극이 득보다 손실로 기울기 쉬우니, 목적 없이 머무는 시간을 줄이는 것이 상책입니다."
      : matched.length
        ? `특히 ${matched.join("과 ")}이 이 공간의 결과 맞아, 머무는 시간만큼 소모 없이 회복과 집중이 쌓입니다.`
        : "당신의 현재 흐름에서 에너지 소모 없이 머물 수 있는 안전 지대입니다.";
    return {
      name:p.name,
      category:p.cats[0],
      reason:`${p.reasonCore} ${matchLine}`,
      actions:p.actions,
      luckOpen:p.luck,
      caution:p.caution,
      avoidTime:p.avoidTime,
    };
  });
}

/* 운명의 좌표 — 태양(3)·달(2)·상승궁(2) 3축 점수로 16개국 중 상위 8개국을 고른다.
   buildPremiumPlaces와 동일한 스코어링 관례를 따른다. */
function buildDestinyAtlas(ctx){
  const sunElem=ctx.elemKey, moonElem=ctx.moon.elem, risingElem=ctx.rising.elem;
  const ranked=DESTINY_ATLAS.map((dest,idx)=>{
    let raw=0;
    if(dest.elems.includes(sunElem)) raw+=3;
    if(dest.elems.includes(moonElem)) raw+=2;
    if(dest.elems.includes(risingElem)) raw+=2;
    raw+=((idx*3+ctx.birthDay+ctx.birthMonth)%4); // 동점 분산 — 생일마다 순위가 달라지게
    return {...dest,raw};
  }).sort((a,b)=>b.raw-a.raw);

  return ranked.slice(0,8).map((dest,rank)=>{
    const matched=[];
    if(dest.elems.includes(sunElem)) matched.push(`태양(${ctx.sun.name})의 ${ELEMENTS[sunElem].name} 기질`);
    if(dest.elems.includes(moonElem)) matched.push(`달(${ctx.moon.name})의 정서 리듬`);
    if(dest.elems.includes(risingElem)) matched.push(`상승궁(${ctx.rising.name})의 대외 리듬`);
    const matchLine=matched.length
      ? `${matched.join("과 ")}이 이 땅의 결과 맞물립니다. 머무는 시간이 그대로 회복과 확장으로 쌓이는 구간입니다.`
      : "원소가 정면으로 겹치지는 않지만, 그래서 오히려 평소 안 쓰던 축을 깨우는 자극형 목적지입니다.";
    return {
      ...dest,
      rank:rank+1,
      matchScore:Math.min(98,58+dest.raw*5),
      matchLine,
    };
  });
}

/* 운명의 수레바퀴 — 금성·화성·달·목성·토성 배치로 연애운을 조립한다.
   transitVenusKey는 오늘의 금성(실측 트랜짓). 없으면 네이탈만으로 계산한다. */
const VENUS_SUPPORT_ELEM={fire:"air",air:"fire",earth:"water",water:"earth"};
function buildWheelOfFortune(ctx,transitVenusKey){
  const v=ctx.venus, mr=ctx.mars, mn=ctx.moon;
  const vLove=VENUS_LOVE[v.key], mLove=MARS_LOVE[mr.key], aLove=MOON_ATTACH[mn.key];
  const jupElem=ctx.jupiter.elem, satElem=ctx.saturn.elem;
  const trap=SATURN_TRAP[satElem], luck=JUPITER_LUCK[jupElem];

  /* ── 게이지 ── */
  const vmRel=elementRelation(v.elem,mr.elem);
  const vnRel=elementRelation(v.elem,mn.elem);
  const tSign=transitVenusKey&&isValidSignKey(transitVenusKey)?SIGNS.find(s=>s.key===transitVenusKey):null;
  const tRel=tSign?elementRelation(v.elem,tSign.elem):null;
  const tBonus=tRel==="same"?12:tRel==="support"?7:tRel==="tension"?-9:0;
  const gauge=Math.max(28,Math.min(97,
    Math.round(luck.lv*0.7)
    +(vmRel==="support"?16:vmRel==="same"?10:4)
    +(vnRel==="support"?11:vnRel==="same"?7:3)
    +tBonus+(ctx.birthDay%5)));
  const phaseKey=gauge>=76?"crown":gauge>=65?"ascent":gauge>=54?"turning":gauge>=45?"descent":"nadir";

  /* ── 금성 × 화성 원소 관계 ── */
  const vmLine={
    same:`금성과 화성이 모두 ${ELEMENTS[v.elem].name} 원소라, 끌림과 행동이 한 방향으로 갑니다. 좋아하면 바로 움직이는 대신 아니라고 판단하면 뒤도 안 돌아보는, 중간 없는 연애를 합니다.`,
    support:`금성(${ELEMENTS[v.elem].name})과 화성(${ELEMENTS[mr.elem].name})이 서로를 밀어주는 관계라 마음과 행동의 속도가 잘 맞습니다. 표현이 자연스럽게 나오는 편이라 오해로 잃는 인연이 적습니다.`,
    tension:`금성(${ELEMENTS[v.elem].name})과 화성(${ELEMENTS[mr.elem].name})의 결이 달라, 마음과 행동이 자주 어긋납니다. 좋아하면서도 밀어내는 행동이 나오는 것이 이 배치가 평생 풀어야 할 숙제입니다.`,
  }[vmRel];

  /* ── 인연 프로필 ── */
  const partnerElem=VENUS_SUPPORT_ELEM[v.elem];
  const compat=getCompat(v.elem,partnerElem);
  const partnerSigns=SIGNS.filter(s=>s.elem===partnerElem).map(s=>s.name).join(" · ");

  /* ── 럭키 윈도우 ── */
  const idx=(key)=>SIGNS.findIndex(s=>s.key===key);
  const luckyDay=LOVE_WEEKDAYS[idx(v.key)%7];
  let avoidDay=LOVE_WEEKDAYS[(idx(ctx.saturn.key)+3)%7];
  if(avoidDay===luckyDay) avoidDay=LOVE_WEEKDAYS[(idx(ctx.saturn.key)+4)%7];

  return {
    phase:{...WHEEL_PHASES[phaseKey],key:phaseKey,gauge},
    transitNote:tSign
      ? `오늘의 금성은 ${tSign.name}을 지나갑니다. 당신의 네이탈 금성(${v.name})과 ${tRel==="same"?"같은 원소라 매력 신호가 그대로 증폭되는":tRel==="support"?"서로 밀어주는 관계라 순풍이 붙는":"결이 어긋나 신호가 왜곡되기 쉬운"} 구간입니다.`
      : "오늘의 금성 위치는 아직 계산 중입니다. 아래 판정은 네이탈 배치만으로 낸 값이며, 트랜짓이 도착하면 게이지가 조정됩니다.",
    venus:{
      tag:vLove.tag,drip:vLove.drip,
      paragraphs:[
        `${v.name} 금성이 당신의 끌림 언어를 정합니다. ${vLove.attract}`,
        `호감이 생겼을 때 당신이 내보내는 신호는 이렇습니다. ${vLove.signal} 본인은 티 안 낸다고 생각하지만 ${v.god}의 방식은 생각보다 잘 읽힙니다.`,
        `반대로 마음이 식는 지점도 분명합니다. ${vLove.killer} 이 선을 넘는 상대와는 시간을 더 써도 회복되지 않으니, 초반에 기준을 말로 정해 두는 편이 유리합니다.`,
        vmLine,
      ],
    },
    mars:{
      tag:mLove.tag,drip:mLove.drip,
      paragraphs:[
        `${mr.name} 화성이 당신의 추진과 밀당을 담당합니다. ${mLove.pursuit}`,
        `갈등 국면에서의 반응은 이렇습니다. ${mLove.conflict}`,
        `화해의 문법은 따로 있습니다. ${mLove.makeup}`,
        `${ctx.saturn.name} 토성이 경고하는 연애 함정은 "${trap.trap}"입니다. ${trap.txt} 관계에서도 같은 패턴이 반복되니, 감정이 올라온 날의 결정은 하루 뒤로 미루는 규칙 하나면 손실 대부분이 막힙니다.`,
      ],
    },
    moon:{
      tag:aLove.tag,drip:aLove.drip,
      paragraphs:[
        `${mn.name} 달이 당신의 애착 방식을 결정합니다. ${aLove.attachment}`,
        `당신이 실제로 듣고 싶은 문장은 이것입니다. ${aLove.needWord} 이 말을 해 주는 사람 앞에서만 방어가 내려갑니다.`,
        `상처가 나는 지점은 정해져 있습니다. ${aLove.wound}`,
        `${ELEMENTS[mn.elem].name} 달이라 회복 속도는 ${mn.elem==="water"?"느리지만 깊습니다. 서둘러 괜찮은 척하면 다음 관계로 감정이 그대로 넘어갑니다":mn.elem==="fire"?"빠릅니다. 다만 빠른 회복을 '괜찮음'으로 착각해 같은 유형을 반복해서 만나는 것이 함정입니다":mn.elem==="earth"?"일정합니다. 시간을 정해 놓고 애도하면 그 기간 안에 실제로 정리됩니다":"머리로 먼저 끝납니다. 논리적으로 정리됐다고 감정까지 끝난 건 아니라는 점만 기억하세요"}.`,
      ],
    },
    timeline:[
      {label:"1개월",title:`${WHEEL_PHASES[phaseKey].name} 진입`,
        text:`${WHEEL_PHASES[phaseKey].advice} 이번 달 당신의 금성(${v.name})은 ${vLove.tag} 모드로 작동하니, ${vLove.signal.split('.')[0]}는 행동이 자연스럽게 늘어납니다.`},
      {label:"3개월",title:`${ctx.jupiter.name} 목성이 여는 구간`,
        text:`목성이 ${ELEMENTS[jupElem].name}에 있어 기회의 형태가 정해져 있습니다. ${luck.txt} 연애에서는 ${LOVE_CHANNELS[jupElem]} 이 경로에서 온 인연은 3개월 안에 관계의 형태가 잡힙니다.`},
      {label:"6개월",title:`${ctx.saturn.name} 토성이 거는 제동`,
        text:`반년 안에 "${trap.trap}"이 관계의 시험대로 올라옵니다. 이 시기의 갈등은 상대의 문제가 아니라 당신의 오래된 패턴이 표면화된 것이라, 여기서 기준을 다시 쓰면 이후 흐름이 통째로 바뀝니다.`},
      {label:"1년",title:`${ctx.sun.name} 태양과 ${mn.name} 달의 재정렬`,
        text:`1년 사이클의 결론은 태양이 원하는 방향과 달이 필요로 하는 안정이 얼마나 맞춰졌는지로 갈립니다. ${vmRel==="tension"?"금성과 화성이 어긋나 있는 배치라, 올해는 상대를 고르는 안목보다 자기 신호를 일관되게 내는 훈련이 승부처입니다":"금성과 화성의 결이 맞는 배치라, 마음을 정하면 실제 관계까지 도달하는 확률이 높은 해입니다"}.`},
    ],
    encounter:{
      elemName:ELEMENTS[partnerElem].name,
      emoji:ELEMENTS[partnerElem].emoji,
      signs:partnerSigns,
      compatTitle:compat.title,
      compatScore:compat.score,
      channel:LOVE_CHANNELS[partnerElem],
      love:compat.detail.love,
      firstSignal:ELEMENTS[partnerElem].love,
      caution:compat.detail.warning,
    },
    luckyWindow:{
      day:luckyDay,
      hours:LOVE_HOURS[idx(mr.key)%6],
      moonPhase:LOVE_MOON_PHASES[idx(mn.key)%5],
      avoidDay,
    },
    greenLights:[
      `${ctx.jupiter.name} 목성 기운이 붙는 자리 — ${LOVE_CHANNELS[jupElem]}`,
      `${vLove.tag} 모드가 먹히는 상대 — ${ELEMENTS[partnerElem].name} 계열(${partnerSigns})`,
      `${WHEEL_PHASES[phaseKey].name}에서는 ${phaseKey==="crown"||phaseKey==="ascent"?"먼저 연락하는 쪽이 주도권을 가져갑니다":"관계를 늘리기보다 있는 관계를 정리하는 쪽이 이깁니다"}`,
    ],
    redFlags:[
      `토성 함정 "${trap.trap}" — 이게 올라오는 날은 중요한 대화를 미루세요`,
      `${mLove.tag} — ${mLove.conflict.split('.')[0]}. 이 패턴이 나오면 대화를 잠시 끊는 게 이득입니다`,
      `${aLove.wound} 이 상황에 놓이면 판단력이 급격히 떨어집니다`,
    ],
    verdict:`${ctx.name}의 이번 사이클 판결: ${phaseKey==="crown"?"지금이 최고점입니다. 호감을 약속으로 바꾸지 않으면 이 흐름은 그냥 지나갑니다.":phaseKey==="ascent"?"흐름이 올라가는 중입니다. 확신이 다 서기를 기다리지 말고 먼저 움직이세요.":phaseKey==="turning"?"애매한 관계 하나가 이번 사이클에 결론이 납니다. 미루면 결정권이 상대에게 넘어갑니다.":phaseKey==="descent"?"새로 벌이지 말고 지키세요. 지금의 승부수는 대체로 되돌아옵니다.":"바닥에서만 방향을 바꿀 수 있습니다. 사람을 늘리기 전에 리듬부터 되찾으세요."}`,
  };
}

function buildPremiumTazzaGuide(ctx){
  const winAreas = ["일", "돈", "관계", "창작", "공부", "이동"];
  return [
    {
      title:"내 인생의 패",
      paragraphs:[
        `당신의 인생 패는 한 방형이 아니라 승률 누적형입니다. ${ctx.mars.name} 화성이 초반 추진력을 만들고 ${ctx.mercury.name} 수성이 변수 판독을 보완해, 큰 승부보다 반복 가능한 이김을 쌓을 때 전체 승률이 가장 높아집니다.`,
        `핵심은 "무조건 이길 판"을 고르는 선구안입니다. 상대의 말보다 흐름과 타이밍을 먼저 읽는 장점이 있어, 들어가지 말아야 할 판을 거르는 순간 승률이 급격히 올라가는 구조를 가집니다.`,
        `위기 국면에서도 당신의 승률을 지키는 카드는 감정 대응이 아니라 운영 규칙입니다. 손절 기준, 시간 제한, 우선순위 1개 고정 같은 룰을 먼저 적용하면 연패를 끊고 장기 승률을 회복할 수 있습니다.`
      ]
    },
    {
      title:"지금 걸어도 되는 판",
      paragraphs:[
        `${ctx.jupiter.name} 목성 흐름이 열리는 영역은 ${winAreas.join(" · ")} 중에서도 지금 가장 에너지가 붙는 축입니다. 특히 작은 실험을 빠르게 반복하는 형태의 도전이 유리합니다.`,
        `일에서는 제안서와 실행안, 돈에서는 고정비 최적화와 수입 다변화, 관계에서는 짧고 명확한 약속이 승률을 높입니다.`,
        `창작과 공부는 완성 욕심보다 공개 가능한 최소 단위로 먼저 내보내세요. 이동운은 목적 없는 이동보다 성과형 이동에서 확률이 올라갑니다.`
      ]
    },
    {
      title:"지금 피해야 하는 판",
      paragraphs:[
        `${ctx.saturn.name} 토성 함정은 ${ctx.tazza.trap.trap}입니다. 감정이 달아오른 상태에서 즉답하거나 즉결하면 손실이 커질 수 있습니다.`,
        `손해 보기 쉬운 선택은 관계에서의 과잉해석, 돈에서의 보상심리 소비, 일에서의 무리한 약속입니다. 이 세 가지는 초반엔 시원하지만 후반에 복구 비용이 큽니다.`,
        `기다려야 하는 이유는 간단합니다. 하루만 간격을 두면 정보가 늘고, 정보가 늘면 블러핑에 휘둘리지 않기 때문입니다.`
      ]
    },
    {
      title:"베팅 타이밍",
      paragraphs:[
        `빠르게 움직여야 하는 시기는 조건이 명확할 때입니다. 책임, 보상, 마감이 문장으로 합의되면 그때는 망설임이 손실입니다.`,
        `관망해야 하는 시기는 감정 피로가 누적된 날입니다. 그날의 결심은 실력보다 기분에 좌우될 확률이 높습니다.`,
        `가장 좋은 방식은 작은 실험 후 증액입니다. 1차는 소액 테스트, 2차는 검증 확대, 3차에서만 본 베팅으로 들어가면 승률이 안정됩니다.`
      ]
    },
    {
      title:"올인하면 위험한 것",
      paragraphs:[
        `올인 위험 대상은 인정 욕구와 자존심 승부입니다. 상대를 이기는 데 집중하면 판을 가져와도 체력이 먼저 무너집니다.`,
        `관계에서는 확인 강박, 돈에서는 단기 수익 집착, 일에서는 완벽주의 집착이 역전패의 시작점이 됩니다.`,
        `특히 불안이 올라오는 밤에는 결정을 줄이세요. 밤의 불안은 현실 신호가 아니라 피로 신호인 경우가 많습니다.`
      ]
    },
    {
      title:"승률을 높이는 방식",
      paragraphs:[
        `성공 전략의 1순위는 감정 관리입니다. 감정이 흔들릴수록 지표를 보고, 지표가 불충분하면 결정을 미루는 규칙을 고정하세요.`,
        `사람을 고르는 기준은 말보다 반복 행동입니다. 약속 이행률, 피드백 태도, 위기 시 책임감이 당신의 필터가 되어야 합니다.`,
        `돈과 시간은 분산보다 우선순위 집중이 유리합니다. 한 번에 한 판만 크게 다루고, 나머지는 방어적으로 운영해야 복리 승률이 쌓입니다.`
      ]
    },
    {
      title:"최종 한 줄 판결",
      paragraphs:[
        `지금 당신의 판은 화려한 올인이 아니라, 손실을 줄이며 승률을 쌓는 장기전입니다.`,
        `사람의 반응에 베팅하지 말고, 내가 반복할 수 있는 루틴에 베팅하세요.`,
        `최종 판결: 지금 당신이 걸어야 할 것은 상대의 마음이 아니라, 무너지지 않는 실행 리듬입니다.`
      ]
    }
  ];
}

/* ════════════════════════════════════════════════════════
   CSS
════════════════════════════════════════════════════════ */
const CSS=`
.ov{font-family:var(--font-body);background:#04021A;min-height:100vh;color:#EFE4C0;overflow-x:hidden;position:relative;}
.ov *{box-sizing:border-box;margin:0;padding:0;}
.ov-home{position:fixed;top:18px;left:18px;z-index:6;display:inline-flex;align-items:center;gap:8px;padding:8px 14px;border-radius:999px;border:1px solid rgba(201,168,76,.45);background:rgba(6,4,18,.7);color:#F0D060;font-family:var(--font-body);font-size:11px;font-weight:600;letter-spacing:.05em;text-decoration:none;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);transition:all .25s;}
.ov-home:hover{background:rgba(201,168,76,.12);border-color:rgba(201,168,76,.7);transform:translateY(-1px);box-shadow:0 10px 24px rgba(201,168,76,.18);}
.ov-home:active{transform:translateY(0);}
.cin{font-family:var(--font-premium);} .cind{font-family:var(--font-decorative);} .mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;}
.ov-stage{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:clamp(24px,4vw,44px) clamp(14px,2.6vw,26px);}
.ov-shell{width:min(100%,560px);}
.ov-wide{width:min(100%,960px);margin:0 auto;padding:clamp(16px,2.2vw,28px) clamp(14px,2vw,22px) clamp(56px,6vw,76px);}
.ov-main-title{font-size:clamp(28px,3.2vw,40px)!important;}
.ov-main-subtitle{font-size:clamp(15px,1.7vw,22px)!important;}
/* ── 타입 스케일 ── */
.ov-h1{font-size:clamp(26px,5vw,38px);line-height:1.18;}
.ov-sec-title{font-size:clamp(19px,2.6vw,24px);line-height:1.3;color:#F0D060;font-weight:700;}
.ov-card-title{font-size:17px;line-height:1.45;color:#F0D060;font-weight:700;}
.ov-eyebrow{font-size:11px;letter-spacing:3px;color:rgba(201,168,76,.62);}
.ov-body{font-size:14px;line-height:1.85;color:rgba(239,228,192,.82);}
.ov-sub{font-size:12.5px;line-height:1.7;color:rgba(239,228,192,.58);}
.ov-label{font-size:11px;letter-spacing:1px;color:rgba(201,168,76,.78);}
/* ── 섹션 헤더 ── */
.shead{display:flex;align-items:center;gap:12px;margin-bottom:18px;}
.shead-ico{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:21px;background:rgba(201,168,76,.08);border:1px solid rgba(201,168,76,.22);flex-shrink:0;}
.shead-ico.crimson{background:rgba(220,20,60,.08);border-color:rgba(220,20,60,.28);}
/* ── 스티키 탭 ── */
.ov-tabs{position:sticky;top:0;z-index:5;display:flex;gap:6px;padding:10px 0 12px;margin-bottom:16px;background:linear-gradient(180deg,rgba(4,2,26,.96) 60%,rgba(4,2,26,0));backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);}
.cosmos{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:0;overflow:hidden;}
.star{position:absolute;border-radius:50%;animation:tw var(--d) ease-in-out infinite alternate;}
@keyframes tw{from{opacity:.05;transform:scale(.8)}to{opacity:1;transform:scale(1)}}
.ember{position:absolute;width:3px;height:3px;border-radius:50%;background:#C9A84C;animation:rise var(--rd) ease-in infinite;}
@keyframes rise{0%{transform:translateY(0) translateX(0);opacity:.9}100%{transform:translateY(-180px) translateX(var(--rx));opacity:0}}
.shooting{position:absolute;width:120px;height:1px;background:linear-gradient(90deg,rgba(201,168,76,0),rgba(201,168,76,.9),rgba(255,255,255,1));animation:shoot var(--sd) ease-in infinite;transform-origin:left center;}
@keyframes shoot{0%{opacity:0;transform:translate(var(--sx),var(--sy)) rotate(-35deg) scaleX(0)}20%{opacity:1;transform:translate(var(--sx),var(--sy)) rotate(-35deg) scaleX(1)}80%{opacity:1;transform:translate(calc(var(--sx) + 300px),calc(var(--sy) + 210px)) rotate(-35deg) scaleX(1)}100%{opacity:0;transform:translate(calc(var(--sx) + 400px),calc(var(--sy) + 280px)) rotate(-35deg) scaleX(0)}}
.pillar{position:fixed;top:0;width:28px;height:100vh;pointer-events:none;z-index:0;}
.pillar-l{left:0;background:linear-gradient(90deg,rgba(201,168,76,.07),transparent);}
.pillar-r{right:0;background:linear-gradient(270deg,rgba(201,168,76,.07),transparent);}
.pillar-cap{position:absolute;left:0;right:0;height:5px;background:linear-gradient(90deg,transparent,rgba(201,168,76,.3),transparent);}
.pillar-flute{position:absolute;left:10px;width:1px;height:100%;background:repeating-linear-gradient(180deg,rgba(201,168,76,.1) 0px,rgba(201,168,76,.1) 40px,transparent 40px,transparent 60px);}
@keyframes lightning{0%,94%{opacity:0}95%{opacity:.35}96%{opacity:0}98%{opacity:.15}100%{opacity:0}}
.lb{position:fixed;top:0;left:0;width:100%;height:100%;background:radial-gradient(ellipse at 50% 20%,rgba(150,180,255,.1),transparent 70%);animation:lightning 9s ease-in-out infinite;pointer-events:none;z-index:0;}
.gb{border:1px solid rgba(201,168,76,.28);}
.gbs{border:1px solid rgba(201,168,76,.6);box-shadow:0 0 36px rgba(201,168,76,.07);}
.gbx{border:1px solid rgba(201,168,76,.75);box-shadow:0 0 60px rgba(201,168,76,.12),inset 0 0 40px rgba(201,168,76,.03);}
.glow{text-shadow:0 0 30px rgba(240,208,80,.5),0 0 60px rgba(240,208,80,.18);color:#F5DC70;}
.glow2{text-shadow:0 0 20px rgba(240,208,80,.35);color:#F0D060;}
.scard{background:rgba(4,2,26,.95);border-radius:16px;padding:clamp(18px,2.4vw,28px);margin-bottom:20px;position:relative;overflow:hidden;}
.scard::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,#C9A84C 30%,#F5DC70 50%,#C9A84C 70%,transparent);}
.pc{background:rgba(255,255,255,.03);border-radius:10px;padding:10px 6px;text-align:center;cursor:pointer;transition:all .3s;border:1px solid rgba(201,168,76,.15);}
.pc:hover,.pc.act{background:rgba(201,168,76,.1);border-color:rgba(201,168,76,.55);transform:translateY(-2px);}
.btn-g{background:linear-gradient(135deg,#C9A84C 0%,#8B6914 100%);color:#04021A;border:none;border-radius:8px;padding:13px 28px;font-family:var(--font-body);font-size:14px;font-weight:700;cursor:pointer;letter-spacing:.02em;transition:all .3s;width:100%;position:relative;overflow:hidden;}
.btn-g:hover{transform:translateY(-2px);box-shadow:0 8px 28px rgba(201,168,76,.4);}
.btn-o{background:transparent;color:#C9A84C;border:1px solid rgba(201,168,76,.45);border-radius:8px;padding:10px 18px;font-family:var(--font-body);font-size:12px;font-weight:600;cursor:pointer;transition:all .3s;letter-spacing:.02em;}
.btn-o:hover{background:rgba(201,168,76,.1);border-color:rgba(201,168,76,.7);}
.btn-tab{background:transparent;border:1px solid rgba(201,168,76,.22);border-radius:10px;padding:11px 14px;min-height:44px;font-family:var(--font-body);font-size:13px;font-weight:600;cursor:pointer;transition:all .3s;letter-spacing:.02em;color:rgba(240,228,192,.62);}
.btn-tab.act{background:rgba(201,168,76,.14);border-color:rgba(201,168,76,.6);color:#C9A84C;}
.inp{background:rgba(255,255,255,.04);border:1px solid rgba(201,168,76,.3);border-radius:8px;padding:11px 14px;color:#EFE4C0;font-family:var(--font-body);font-size:15px;width:100%;outline:none;transition:all .3s;-webkit-appearance:none;color-scheme:dark;}
.inp:focus{border-color:rgba(201,168,76,.7);box-shadow:0 0 0 3px rgba(201,168,76,.07);}
.inp::placeholder{color:rgba(239,228,192,.2);}
.sbar{background:rgba(255,255,255,.07);border-radius:4px;height:5px;overflow:hidden;}
.sfill{height:100%;border-radius:4px;background:linear-gradient(90deg,#6B2A00,#C9A84C,#F5DC70);transition:width 1.2s cubic-bezier(.22,1,.36,1);}
@keyframes unroll{from{max-height:0;opacity:0}to{max-height:1200px;opacity:1}}
.scroll-reveal{animation:unroll .8s cubic-bezier(.25,.46,.45,.94) forwards;overflow:hidden;}
.ring{width:64px;height:64px;border:2px solid rgba(201,168,76,.15);border-top-color:#C9A84C;border-radius:50%;animation:spin 1s linear infinite;}
@keyframes spin{to{transform:rotate(360deg)}}
.ring2{width:80px;height:80px;border:1px solid rgba(201,168,76,.08);border-bottom-color:rgba(201,168,76,.4);border-radius:50%;animation:spin 1.8s linear infinite reverse;position:absolute;top:-8px;left:-8px;}
.oracle-scroll{background:linear-gradient(180deg,rgba(20,14,4,.9),rgba(10,6,0,.95));border-radius:12px;padding:20px;position:relative;}
.oracle-scroll::before,.oracle-scroll::after{content:'';position:absolute;left:10px;right:10px;height:3px;border-radius:3px;background:linear-gradient(90deg,transparent,rgba(201,168,76,.5),rgba(240,220,100,.8),rgba(201,168,76,.5),transparent);}
.oracle-scroll::before{top:0;} .oracle-scroll::after{bottom:0;}
.compat-ring{border-radius:50%;display:flex;align-items:center;justify-content:center;animation:pulse-ring 3s ease-in-out infinite;}
@keyframes pulse-ring{0%,100%{box-shadow:0 0 0 0 rgba(201,168,76,.3)}50%{box-shadow:0 0 0 12px rgba(201,168,76,0)}}
@keyframes oracleGlow{0%,100%{box-shadow:0 0 20px rgba(201,168,76,.08)}50%{box-shadow:0 0 40px rgba(201,168,76,.18)}}
.oglow{animation:oracleGlow 4s ease-in-out infinite;}
.fi{animation:fi .6s cubic-bezier(.22,1,.36,1) forwards;}
@keyframes fi{from{opacity:0;transform:translateY(18px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
.su{animation:su .5s ease forwards;}
@keyframes su{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
.compat-bar-wrap{position:relative;height:7px;border-radius:4px;overflow:hidden;background:rgba(255,255,255,.06);}
.compat-bar{position:absolute;top:0;left:0;height:100%;border-radius:4px;}
/* ── 타짜 카드 스타일 ── */
.tazza-bg{background:radial-gradient(ellipse at top,rgba(20,0,0,.98),rgba(4,2,10,.99));border:1px solid rgba(180,0,0,.4);position:relative;overflow:hidden;}
.tazza-bg::after{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,#8B0000 30%,#DC143C 50%,#8B0000 70%,transparent);}
.tazza-felt{background:repeating-linear-gradient(45deg,rgba(0,60,0,.15) 0px,rgba(0,60,0,.15) 1px,transparent 1px,transparent 10px);}
.card-flip{width:52px;height:72px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:22px;position:relative;border:1px solid rgba(255,255,255,.15);}
.card-red{background:linear-gradient(135deg,#1a0000,#2d0000);box-shadow:0 4px 12px rgba(220,20,60,.3);}
.card-dark{background:linear-gradient(135deg,#0d0d1a,#1a1a2e);box-shadow:0 4px 12px rgba(0,0,100,.3);}
/* ── 악마 계약서 ── */
.blood-bg{background:radial-gradient(ellipse at center,rgba(30,0,0,.98),rgba(4,0,8,.99));border:1px solid rgba(140,0,0,.5);}
.blood-seal{border-radius:50%;display:flex;align-items:center;justify-content:center;animation:seal-pulse 3s ease-in-out infinite;}
@keyframes seal-pulse{0%,100%{box-shadow:0 0 20px rgba(180,0,0,.3)}50%{box-shadow:0 0 50px rgba(220,20,60,.5)}}
.contract-line{border-bottom:1px solid rgba(140,0,0,.4);padding-bottom:12px;margin-bottom:12px;}
@keyframes drip{0%{transform:scaleY(0);opacity:.9}60%{transform:scaleY(1);opacity:.8}100%{transform:scaleY(1) translateY(6px);opacity:0}}
.blood-drip{width:2px;height:18px;background:linear-gradient(180deg,#DC143C,rgba(139,0,0,0));animation:drip 2.2s ease-in infinite;border-radius:0 0 2px 2px;transform-origin:top;will-change:transform,opacity;}
/* ── K-직장인 채팅 ── */
.chat-bg{background:#0A0A0F;border-radius:14px;padding:16px;border:1px solid rgba(201,168,76,.2);}
.chat-bubble-me{background:rgba(201,168,76,.15);border-radius:14px 14px 4px 14px;padding:9px 13px;max-width:75%;align-self:flex-end;border:1px solid rgba(201,168,76,.25);}
.chat-bubble-boss{background:rgba(255,255,255,.06);border-radius:14px 14px 14px 4px;padding:9px 13px;max-width:75%;border:1px solid rgba(255,255,255,.1);}
.gauge-bar{height:10px;border-radius:5px;overflow:hidden;background:rgba(255,255,255,.07);}
.gauge-fill{height:100%;border-radius:5px;transition:width 1.2s cubic-bezier(.22,1,.36,1);}
/* ── 여행 티켓 ── */
.ticket-bg{background:linear-gradient(135deg,rgba(20,6,0,.98),rgba(8,4,20,.98));border:1px solid rgba(201,168,76,.4);position:relative;}
.ticket-hole{width:20px;height:20px;border-radius:50%;background:#04021A;border:1px solid rgba(201,168,76,.3);}
.ticket-dash{border-top:2px dashed rgba(201,168,76,.25);}
.spot-card{background:rgba(255,255,255,.03);border-radius:10px;padding:12px;border:1px solid rgba(201,168,76,.15);cursor:pointer;transition:all .3s;}
.spot-card:hover{background:rgba(201,168,76,.07);border-color:rgba(201,168,76,.4);}
@media (min-width: 1024px){
  .ov-shell{width:min(100%,640px);}
  .ov-wide{width:min(100%,1120px);}
  .ov-home{top:22px;left:22px;font-size:12px;padding:10px 16px;}
}
@media (max-width: 768px){
  .ov-home{top:10px;left:10px;font-size:11px;padding:8px 12px;}
  .ov-wide{padding:12px 12px 48px;}
  .planet-grid{grid-template-columns:repeat(4,1fr)!important;gap:6px!important;}
  .scard{border-radius:14px;}
  .shead-ico{width:38px;height:38px;font-size:18px;border-radius:10px;}
}
@media (prefers-reduced-motion: reduce){
  .star,.ember,.shooting,.lb,.ring,.ring2,.compat-ring,.oglow,.blood-seal,.blood-drip{animation:none!important;}
  .fi,.su,.scroll-reveal{animation-duration:.01ms!important;}
  .sfill,.gauge-fill{transition:none!important;}
}
::-webkit-scrollbar{width:3px;}
::-webkit-scrollbar-thumb{background:rgba(201,168,76,.25);border-radius:2px;}
.rel{position:relative;z-index:1;}
`;

/* ════════════════════════════════════════════════════════
   COSMOS BACKGROUND
════════════════════════════════════════════════════════ */
function Cosmos(){
  const pr=(i,s=0)=>{
    const x=Math.sin((i+1)*12.9898+(s+1)*78.233)*43758.5453;
    return x-Math.floor(x);
  };
  const stars=Array.from({length:75},(_,i)=>({
    id:i,
    x:pr(i,1)*100,
    y:pr(i,2)*100,
    sz:pr(i,3)*2.2+.3,
    d:(pr(i,4)*4+2).toFixed(1),
    bright:i<18
  }));
  const embers=Array.from({length:10},(_,i)=>({
    id:i,
    x:pr(i,5)*100,
    rd:(pr(i,6)*4+4).toFixed(1),
    rx:`${(pr(i,7)*40-20).toFixed(0)}px`,
    delay:`${(i*.7).toFixed(1)}s`,
    bot:pr(i,8)*20
  }));
  const shoots=Array.from({length:3},(_,i)=>({
    id:i,
    sx:`${pr(i,9)*60+10}vw`,
    sy:`${pr(i,10)*30}vh`,
    sd:`${(pr(i,11)*12+10).toFixed(1)}s`,
    delay:`${i*4}s`
  }));
  return(
    <div className="cosmos">
      <div className="lb"/>
      <div className="pillar pillar-l"><div className="pillar-flute"/><div className="pillar-cap" style={{top:0}}/><div className="pillar-cap" style={{bottom:0}}/></div>
      <div className="pillar pillar-r"><div className="pillar-flute"/><div className="pillar-cap" style={{top:0}}/><div className="pillar-cap" style={{bottom:0}}/></div>
      {stars.map(s=><div key={s.id} className="star" style={{left:`${s.x}%`,top:`${s.y}%`,width:`${s.sz}px`,height:`${s.sz}px`,background:s.bright?'rgba(240,228,180,.9)':'rgba(200,175,100,.5)','--d':`${s.d}s`,animationDelay:`${(s.id*.09).toFixed(1)}s`}}/>)}
      {embers.map(e=><div key={e.id} className="ember" style={{left:`${e.x}%`,bottom:`${e.bot}%`,'--rd':`${e.rd}s`,'--rx':e.rx,animationDelay:e.delay}}/>)}
      {shoots.map(s=><div key={s.id} className="shooting" style={{'--sx':s.sx,'--sy':s.sy,'--sd':s.sd,animationDelay:s.delay,top:0,left:0}}/>)}
    </div>
  );
}

function Divider(){
  return(
    <div style={{display:'flex',alignItems:'center',gap:10,margin:'14px 0'}}>
      <div style={{flex:1,height:.5,background:'linear-gradient(90deg,transparent,rgba(201,168,76,.38))'}}/>
      <span style={{color:'#C9A84C',fontFamily:"var(--font-decorative)",fontSize:11,letterSpacing:6}}>✦ ✦ ✦</span>
      <div style={{flex:1,height:.5,background:'linear-gradient(270deg,transparent,rgba(201,168,76,.38))'}}/>
    </div>
  );
}

function SectionHead({icon,kicker,title,tone}){
  const crimson=tone==='crimson';
  return(
    <div className="shead">
      <div className={`shead-ico${crimson?' crimson':''}`} aria-hidden="true">{icon}</div>
      <div>
        <p className="cin ov-eyebrow" style={crimson?{color:'rgba(220,20,60,.62)'}:undefined}>{kicker}</p>
        <h3 className="ov-sec-title" style={crimson?{color:'#DC143C'}:undefined}>{title}</h3>
      </div>
    </div>
  );
}

/* 정밀 천문 계산 함수(/js/olympus-oracle.js의 window.__olympusComputePlacements) 로더 */
function ensureOracleCompute(){
  if (typeof window==='undefined') return Promise.reject(new Error('no window'));
  if (typeof window.__olympusComputePlacements==='function') return Promise.resolve(window.__olympusComputePlacements);
  return new Promise((resolve,reject)=>{
    const settle=()=>{
      if (typeof window.__olympusComputePlacements==='function') resolve(window.__olympusComputePlacements);
      else reject(new Error('olympus compute fn missing'));
    };
    const existing=document.querySelector('script[src*="/js/olympus-oracle.js"]');
    if (existing){ setTimeout(settle,800); return; }
    const s=document.createElement('script');
    s.src='/js/olympus-oracle.js';
    s.async=true;
    s.onload=settle;
    s.onerror=()=>reject(new Error('olympus oracle script load failed'));
    document.head.appendChild(s);
  });
}

/* 직접 입력(date/time 문자열) → Swiss 계산 payload (서울 좌표·KST 기본) */
function buildSwissPayload(dateStr,timeStr){
  const parts=String(dateStr||'').split('-').map(Number);
  if (parts.length<3||parts.some(n=>!Number.isFinite(n))) return null;
  const t=String(timeStr||'').split(':').map(Number);
  return {
    year:parts[0], month:parts[1], day:parts[2],
    hour:Number.isFinite(t[0])?t[0]:12, minute:Number.isFinite(t[1])?t[1]:0,
    timezone:9, lat:37.5665, lon:126.9780,
  };
}

/* ════════════════════════════════════════════════════════
   INTRO / INPUT / ORACLE-INPUT / LOADING
════════════════════════════════════════════════════════ */
function Intro({onStart,onOracle}){
  return(
    <div className="rel fi ov-stage" style={{textAlign:'center'}}>
      <p className="cin ov-eyebrow" style={{letterSpacing:8,marginBottom:10}}>CODE : DESTINY</p>
      <div style={{fontSize:18,margin:'8px 0',letterSpacing:16,color:'rgba(201,168,76,.5)'}}>⊹ ✦ ⊹</div>
      <h1 className="cind glow ov-main-title" style={{fontWeight:700,letterSpacing:4,lineHeight:1.2,marginBottom:6}}>OLYMPUS</h1>
      <h2 className="cin ov-main-subtitle" style={{fontWeight:400,color:'#C9A84C',letterSpacing:6,marginBottom:4}}>VIP LOUNGE</h2>
      <p style={{fontSize:13,color:'rgba(239,228,192,.45)',letterSpacing:4,marginBottom:30}}>별로 보는 인생 스포일러</p>
      <div className="gbx ov-shell" style={{borderRadius:20,padding:'28px 24px',background:'rgba(4,2,26,.98)',marginBottom:22}}>
        <p className="cin ov-label" style={{letterSpacing:4,marginBottom:14}}>스위스 천문력 기반 8대 배치 분석</p>
        <div style={{marginBottom:18}}>
          {[["☀️","태양/달/상승","나의 본질 — 실측 천문 계산"],["📐","밸런스/어스펙트","원소·모달리티와 행성 각도"],["💘","금성/화성","사랑과 욕망"],["🃏","타짜","인생 베팅 스타일"],["👹","악마","운명의 계약서"],["🧭","아스트로맵","오피스 생존기 & 세계 여행 스팟"]].map(([e,t,s],i,a)=>(
            <div key={i} style={{display:'flex',alignItems:'center',gap:12,padding:'10px 0',borderBottom:i<a.length-1?'1px solid rgba(201,168,76,.07)':'none'}}>
              <span style={{fontSize:18,minWidth:26}}>{e}</span>
              <div style={{textAlign:'left'}}>
                <div style={{fontSize:14,fontWeight:600,color:'rgba(201,168,76,.85)'}}>{t}</div>
                <div style={{fontSize:12.5,color:'rgba(239,228,192,.5)',marginTop:2}}>{s}</div>
              </div>
            </div>
          ))}
        </div>
        <button className="btn-g" onClick={onStart} style={{marginBottom:9}}>신탁 받으러 가기 →</button>
        <button className="btn-o" onClick={onOracle} style={{width:'100%',padding:'10px'}}>오늘의 신탁만 보기</button>
      </div>
    </div>
  );
}

function Input({onSubmit,onBack}){
  const [name,setName]=useState('');
  const [date,setDate]=useState('');
  const [time,setTime]=useState('');
  const [err,setErr]=useState('');
  const go=()=>{if(!date){setErr('생년월일은 필수입니다');return;}setErr('');onSubmit({name,date,time});};
  const labelStyle={fontSize:9,color:'rgba(201,168,76,.6)',letterSpacing:2,display:'block',marginBottom:5};
  // time input needs WebkitAppearance auto to show native clock picker
  const timeStyle={
    background:'rgba(255,255,255,.04)',
    border:'1px solid rgba(201,168,76,.3)',
    borderRadius:8,
    padding:'11px 14px',
    color:'#EFE4C0',
    fontSize:14,
    width:'100%',
    outline:'none',
    colorScheme:'dark',
    WebkitAppearance:'auto',
    appearance:'auto',
    transition:'border-color .3s',
  };
  return(
    <div className="rel fi ov-stage">
      <div className="gbx ov-shell" style={{borderRadius:20,padding:'30px 22px',background:'rgba(4,2,26,.98)'}}>
        <button className="btn-o" onClick={onBack} style={{padding:'6px 12px',fontSize:10,marginBottom:16}}>← 돌아가기</button>
        <div style={{textAlign:'center',marginBottom:22}}>
          <p className="cin ov-eyebrow" style={{letterSpacing:5,marginBottom:8}}>ORACLE INPUT</p>
          <h2 className="cin glow2" style={{fontSize:'clamp(20px,2.6vw,24px)',letterSpacing:2}}>신탁 정보 입력</h2>
          <p style={{fontSize:13.5,color:'rgba(239,228,192,.5)',marginTop:8}}>스위스 천문력으로 당신의 우주 좌표를 계산합니다</p>
        </div>
        <Divider/>
        <div style={{display:'flex',flexDirection:'column',gap:13}}>
          <div>
            <label className="cin" style={labelStyle}>이름 (선택)</label>
            <input className="inp" type="text" value={name} onChange={e=>setName(e.target.value)} placeholder="신들이 뭐라 부를까요"/>
          </div>
          <div>
            <label className="cin" style={labelStyle}>생년월일 *</label>
            <input className="inp" type="date" value={date} onChange={e=>setDate(e.target.value)} max="2010-12-31" min="1920-01-01"/>
          </div>
          <div>
            <label className="cin" style={labelStyle}>태어난 시간 (선택)</label>
            <input type="time" value={time} onChange={e=>setTime(e.target.value)} style={timeStyle}/>
            <p style={{fontSize:12,color:'rgba(239,228,192,.42)',marginTop:6,paddingLeft:2}}>입력 시 상승궁(어센던트)까지 실측 계산됩니다 — 모르면 비워두세요</p>
          </div>
        </div>
        {err&&<p style={{color:'#E85D1B',fontSize:11,marginTop:8,textAlign:'center'}}>{err}</p>}
        <Divider/>
        <button className="btn-g" onClick={go}>올림포스에 입장하기</button>
        <p style={{fontSize:10,color:'rgba(239,228,192,.18)',textAlign:'center',marginTop:10,cursor:'pointer',textDecoration:'underline'}} onClick={()=>onSubmit({name:'아무개',date:'1995-06-15',time:'09:00'})}>테스트 데이터로 시작</p>
      </div>
    </div>
  );
}

function OracleInput({onSubmit,onBack}){
  const [date,setDate]=useState('');
  const [err,setErr]=useState('');
  const go=()=>{
    if(!date){setErr('생년월일을 입력해주세요');return;}setErr('');
    const d=new Date(date),m=d.getMonth()+1,day=d.getDate(),sk=getSign(m,day);
    const signInfo=SIGNS.find(s=>s.key===sk),today=new Date();
    const oracle=DAILY_ORACLES[sk][(today.getDate()+today.getMonth())%2];
    onSubmit({signInfo,oracle,elemKey:signInfo.elem,element:ELEMENTS[signInfo.elem]});
  };
  return(
    <div className="rel fi ov-stage">
      <div className="gbx ov-shell" style={{borderRadius:20,padding:'30px 22px',background:'rgba(4,2,26,.98)'}}>
        <button className="btn-o" onClick={onBack} style={{padding:'6px 12px',fontSize:10,marginBottom:16}}>← 돌아가기</button>
        <div style={{textAlign:'center',marginBottom:22}}>
          <div style={{fontSize:32,marginBottom:8}}>🔮</div>
          <p className="cin ov-eyebrow" style={{letterSpacing:5,marginBottom:7}}>DAILY PROPHECY</p>
          <h2 className="cin glow2" style={{fontSize:'clamp(20px,2.6vw,24px)',letterSpacing:2}}>오늘의 신탁</h2>
        </div>
        <Divider/>
        <div>
          <label className="cin" style={{fontSize:9,color:'rgba(201,168,76,.6)',letterSpacing:2,display:'block',marginBottom:5}}>생년월일</label>
          <input className="inp" type="date" value={date} onChange={e=>setDate(e.target.value)} max="2010-12-31" min="1920-01-01"/>
        </div>
        {err&&<p style={{color:'#E85D1B',fontSize:11,marginTop:8,textAlign:'center'}}>{err}</p>}
        <Divider/>
        <button className="btn-g" onClick={go}>신탁 듣기</button>
      </div>
    </div>
  );
}

function Loading(){
  const [ph,setPh]=useState(0);
  const ps=["제우스가 올림포스 회의 소집 중...","아폴론이 태양 에너지 스캔 중...","헤르메스가 우주 좌표 계산 중...","타짜 패 분류 중...","악마 계약서 작성 중...","신탁 완성 — 피티아가 입을 열다"];
  useEffect(()=>{const t=setInterval(()=>setPh(p=>Math.min(p+1,ps.length-1)),560);return()=>clearInterval(t);},[]);
  return(
    <div className="rel ov-stage" style={{textAlign:'center',padding:24}}>
      <div style={{position:'relative',width:92,height:92,margin:'0 auto 28px'}}>
        <div className="ring2"/><div className="ring" style={{position:'absolute',top:8,left:8}}/>
        <div style={{position:'absolute',top:'50%',left:'50%',transform:'translate(-50%,-50%)',fontSize:26}}>⚡</div>
      </div>
      <h2 className="cin glow2" style={{fontSize:'clamp(19px,2.6vw,23px)',marginBottom:10}}>신탁 생성 중</h2>
      <p style={{fontSize:13.5,color:'rgba(201,168,76,.85)',height:20}}>{ps[ph]}</p>
      <div style={{display:'flex',gap:5,justifyContent:'center',marginTop:22}}>
        {ps.map((_,i)=><div key={i} style={{width:i<=ph?16:5,height:4,borderRadius:2,background:i<=ph?'#C9A84C':'rgba(201,168,76,.15)',transition:'all .4s'}}/>)}
      </div>
    </div>
  );
}

function DailyOracleResult({data,onBack}){
  const {signInfo,oracle,elemKey,element}=data;
  const ec={fire:'#E85D1B',earth:'#7AB540',air:'#5BA3C9',water:'#4A8FD4'};
  const today=new Date(),ds=`${today.getFullYear()}년 ${today.getMonth()+1}월 ${today.getDate()}일`;
  return(
    <div className="rel ov-wide">
      <div className="fi" style={{textAlign:'center',padding:'26px 0 18px'}}>
        <p className="cin ov-eyebrow" style={{letterSpacing:6,marginBottom:10}}>{ds} 신탁</p>
        <div style={{fontSize:50,marginBottom:10,lineHeight:1}}>{signInfo.sym}</div>
        <h1 className="cind glow ov-h1" style={{marginBottom:6}}>{signInfo.name}</h1>
        <p style={{fontSize:14,color:'#C9A84C',letterSpacing:2,marginBottom:4}}>{signInfo.god}의 수호</p>
        <div style={{display:'inline-flex',alignItems:'center',gap:8,background:element.dark,border:`1px solid ${ec[elemKey]}28`,borderRadius:20,padding:'5px 14px',marginTop:8}}>
          <span style={{fontSize:13}}>{element.emoji}</span><span style={{fontSize:11,color:ec[elemKey]}}>{element.faction}</span>
        </div>
      </div>
      <Divider/>
      <div className="scard gb oglow scroll-reveal" style={{background:'rgba(12,8,2,.98)'}}>
        <SectionHead icon={oracle.icon} kicker={`${oracle.god}의 신탁`} title={`${signInfo.name}의 오늘 — ${oracle.theme}`}/>
        <div className="oracle-scroll">
          <p className="cin ov-eyebrow" style={{letterSpacing:4,marginBottom:10,textAlign:'center'}}>✦ PROPHETIA ✦</p>
          <p style={{fontSize:15,lineHeight:2.05,color:'rgba(239,228,192,.9)',textAlign:'center',fontStyle:'italic'}}>{oracle.prophecy}</p>
        </div>
        <Divider/>
        <div style={{background:'rgba(201,168,76,.05)',borderRadius:10,padding:14,border:'1px solid rgba(201,168,76,.12)'}}>
          <p className="cin ov-label" style={{marginBottom:7}}>⚡ 오늘의 지령</p>
          <p className="ov-body">{oracle.action}</p>
        </div>
        <div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:8,marginTop:12}}>
          {[{l:"행운의 색",v:oracle.lucky},{l:"행운의 수",v:oracle.num},{l:"황금 시간",v:oracle.time}].map((it,i)=>(
            <div key={i} style={{background:'rgba(255,255,255,.03)',borderRadius:10,padding:'11px 8px',textAlign:'center',border:'1px solid rgba(201,168,76,.1)'}}>
              <p style={{fontSize:11,color:'rgba(201,168,76,.6)',marginBottom:4}}>{it.l}</p>
              <p style={{fontSize:14,fontWeight:600,color:'#F0D060'}}>{it.v}</p>
            </div>
          ))}
        </div>
      </div>
      <Divider/>
      <div style={{textAlign:'center'}}><button className="btn-o" onClick={onBack}>다른 별자리 보기</button></div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   RESULT — MAIN TABS
════════════════════════════════════════════════════════ */
function TabResult({result,onReset}){
  const [tab,setTab]=useState('profile');
  const tabs=[{k:'profile',l:'내 신탁'},{k:'compat',l:'궁합'},{k:'oracle',l:'오늘 운세'}];
  const swiss=result.calcMode==='swiss';
  return(
    <div className="rel ov-wide">
      <div className="fi" style={{textAlign:'center',padding:'26px 0 18px'}}>
        <p className="cin ov-eyebrow" style={{letterSpacing:6,marginBottom:10}}>ORACLE COMPLETE</p>
        <div style={{fontSize:52,marginBottom:10,lineHeight:1}}>{result.sun.sym}</div>
        <h1 className="cind glow ov-h1" style={{marginBottom:6}}>{result.name}의 신탁</h1>
        <p style={{fontSize:15,color:'#C9A84C'}}>{result.sun.name} ✦ {result.sun.dates}</p>
        <div style={{display:'flex',justifyContent:'center',gap:8,flexWrap:'wrap',marginTop:12}}>
          <div style={{display:'inline-flex',alignItems:'center',gap:7,background:result.element.dark,border:'1px solid rgba(201,168,76,.22)',borderRadius:20,padding:'6px 14px'}}>
            <span style={{fontSize:13}}>{result.element.emoji}</span>
            <span style={{fontSize:12,color:'rgba(201,168,76,.9)'}}>{result.element.faction}</span>
          </div>
          <div style={{display:'inline-flex',alignItems:'center',gap:6,background:'rgba(201,168,76,.06)',border:'1px solid rgba(201,168,76,.22)',borderRadius:20,padding:'6px 14px'}}>
            <span style={{fontSize:12}}>{swiss?'🔭':'📐'}</span>
            <span style={{fontSize:11,color:'rgba(239,228,192,.65)'}}>{swiss?'스위스 천문력 정밀 계산':'간이 계산 (근사치)'}</span>
          </div>
        </div>
      </div>
      <div className="ov-tabs" role="tablist">
        {tabs.map(t=><button key={t.k} role="tab" aria-selected={tab===t.k} aria-label={`${t.l} 탭`} className={`btn-tab${tab===t.k?' act':''}`} onClick={()=>setTab(t.k)} style={{flex:1}}>{t.l}</button>)}
      </div>
      {tab==='profile' && <ProfileTab result={result}/>}
      {tab==='compat'  && <CompatTab myResult={result}/>}
      {tab==='oracle'  && <OracleTab result={result}/>}
      <Divider/>
      <div style={{textAlign:'center',paddingTop:4}}>
        <button className="btn-o" onClick={onReset} aria-label="처음으로 돌아가 다른 사람 분석하기">다른 사람 분석하기</button>
        <p style={{fontSize:11,color:'rgba(239,228,192,.3)',marginTop:14,lineHeight:1.9}}>* 올림포스 신들의 유희입니다. 실제 인생 결정에 사용 시 신들은 책임지지 않습니다.</p>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   PROFILE TAB — 모든 섹션 포함
════════════════════════════════════════════════════════ */
function ProfileTab({result}){
  const [ap,setAp]=useState(0);
  const planets=[result.sun,result.moon,result.rising,result.venus,result.mars,result.mercury,result.jupiter,result.saturn];
  const sel=planets[ap];
  const selDecan=decanSignOf(sel.key,sel.deg);
  const fmtDeg=(p)=>Number.isFinite(p.deg)?` ${Math.floor(p.deg)}°`:'';
  return(
    <div>
      {/* 8행성 배치 */}
      <p className="cin ov-label" style={{textAlign:'center',marginBottom:10}}>8대 배치 — 행성이 머무는 별자리</p>
      <div className="planet-grid" style={{display:'grid',gridTemplateColumns:'repeat(8,1fr)',gap:5,marginBottom:10}}>
        {planets.map((p,i)=>(
          <button key={i} className={`pc${ap===i?' act':''}`} onClick={()=>setAp(i)} aria-label={`${p.planet} ${p.name} 상세 보기`} style={{font:'inherit',color:'inherit'}}>
            <div style={{fontSize:15,marginBottom:2}}>{p.emoji}</div>
            <div className="cin" style={{fontSize:9,color:'#C9A84C',lineHeight:1.25}}>{p.planet}</div>
            <div style={{fontSize:11,marginTop:2,color:'rgba(239,228,192,.8)'}}>{p.sym}{fmtDeg(p)}</div>
          </button>
        ))}
      </div>
      <div className="scard gb fi" key={ap} style={{marginBottom:14}}>
        <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:12}}>
          <span style={{fontSize:24}}>{sel.emoji}</span>
          <div>
            <p className="cin ov-label">{sel.planet} — {sel.god}</p>
            <p className="ov-card-title">{sel.name} {sel.sym}{Number.isFinite(sel.deg)?` · ${sel.deg.toFixed(1)}°`:''}</p>
          </div>
        </div>
        <p style={{color:'#F5DC70',fontWeight:600,fontSize:14,marginBottom:8,lineHeight:1.6}}>"{sel.pd.h}"</p>
        <p className="ov-body">{sel.pd.t}</p>
        <div style={{display:'flex',flexWrap:'wrap',gap:6,marginTop:12}}>
          <span style={{fontSize:11.5,color:'rgba(201,168,76,.8)',background:'rgba(201,168,76,.06)',border:'1px solid rgba(201,168,76,.18)',borderRadius:20,padding:'4px 11px'}}>{MODALITIES[modalityOf(sel.key)].short}궁 · {ELEMENTS[sel.elem].name}</span>
          {selDecan&&(
            <span style={{fontSize:11.5,color:'rgba(201,168,76,.8)',background:'rgba(201,168,76,.06)',border:'1px solid rgba(201,168,76,.18)',borderRadius:20,padding:'4px 11px'}}>
              {selDecan.decan}데칸{selDecan.decan>1?` — ${selDecan.sign.name} 결 가미`:' — 순수 발현'}
            </span>
          )}
          {sel.planet==='상승궁'&&result.risingApprox&&(
            <span style={{fontSize:11.5,color:'rgba(239,228,192,.5)',background:'rgba(255,255,255,.03)',border:'1px solid rgba(201,168,76,.14)',borderRadius:20,padding:'4px 11px'}}>출생 시간 입력 시 정밀 계산</span>
          )}
        </div>
      </div>

      <BalanceSection balance={result.balance}/>
      <AspectSection aspects={result.aspects}/>

      <PremiumOracleSection result={result}/>

      {/* SECTION 1 — 팩폭 주의보 */}
      <FakbokSection fakbok={result.fakbok} result={result}/>

      {/* SECTION 2 — 아프로디테의 픽 */}
      <div className="scard gb">
        <SectionHead icon="💘" kicker="SECTION 2" title="아프로디테의 픽"/>
        {[{e:"💘",l:"연애·플러팅 스타일",t:result.venus.pd.t},{e:"🔥",l:"욕망·행동력 스위치",t:result.mars.pd.t}].map((it,i)=>(
          <div key={i} style={{background:'rgba(232,93,27,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(232,93,27,.18)',marginBottom:i<1?10:0}}>
            <p style={{fontSize:13,color:'#E85D1B',fontWeight:600,marginBottom:5}}>{it.e} {it.l}</p>
            <p className="ov-body">{it.t}</p>
          </div>
        ))}
        <div style={{marginTop:10,background:result.element.dark,borderRadius:10,padding:14,border:'1px solid rgba(201,168,76,.1)'}}>
          <p style={{fontSize:13,color:'rgba(201,168,76,.85)',fontWeight:600,marginBottom:5}}>{result.element.emoji} {result.element.faction} 연애 특징</p>
          <p className="ov-body" style={{color:'rgba(239,228,192,.75)'}}>{result.element.love}</p>
        </div>
      </div>

      {/* SECTION 3 — 타짜: 인생 베팅 스타일 */}
      <TazzaSection data={result.tazza} marsSign={result.mars} jupSign={result.jupiter} satSign={result.saturn} guide={result.premium?.tazzaGuide || []}/>

      {/* SECTION 4 — 악마 계약서 */}
      <DevilSection devil={result.devil} rising={result.rising} mercury={result.mercury}/>

      {/* SECTION 5 — K-직장인 오피스 */}
      <OfficeSection office={result.office} sunName={result.sun.name} mercName={result.mercury.name}/>

      {/* SECTION 6 — 아스트로 맵 세계 */}
      <DestinySpotSection atlas={result.atlas} elemKey={result.elemKey}/>

      {/* BONUS — 운명의 수레바퀴 (연애운) */}
      <WheelOfFortuneSection result={result}/>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   원소·모달리티 밸런스 (전문 섹션)
════════════════════════════════════════════════════════ */
function BalanceSection({balance}){
  if(!balance) return null;
  const ec={fire:'#E85D1B',earth:'#7AB540',air:'#5BA3C9',water:'#4A8FD4'};
  const elemRows=['fire','earth','air','water'].map((k)=>({k,label:ELEMENTS[k].name,emoji:ELEMENTS[k].emoji,v:balance.elems[k],c:ec[k]}));
  const modRows=['cardinal','fixed','mutable'].map((k)=>({k,label:MODALITIES[k].name,v:balance.mods[k],c:'#C9A84C'}));
  const Bar=({rows})=>(
    <div style={{display:'flex',flexDirection:'column',gap:9}}>
      {rows.map((r)=>(
        <div key={r.k}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',marginBottom:4}}>
            <span style={{fontSize:13,color:'rgba(239,228,192,.8)'}}>{r.emoji?`${r.emoji} `:''}{r.label}</span>
            <span className="mono" style={{fontSize:13,fontWeight:700,color:r.c}}>{r.v}<span style={{fontSize:10,color:'rgba(239,228,192,.4)',fontWeight:400}}>/{balance.total}</span></span>
          </div>
          <div className="sbar"><div className="sfill" style={{width:`${(r.v/balance.total)*100}%`,background:`linear-gradient(90deg,${r.c}55,${r.c})`}}/></div>
        </div>
      ))}
    </div>
  );
  return(
    <div className="scard gb">
      <SectionHead icon="⚖️" kicker="CHART BALANCE" title="원소·모달리티 밸런스"/>
      <p className="ov-sub" style={{marginBottom:14}}>8개 배치가 4원소(기질)와 3모달리티(행동 양식)에 어떻게 분포하는지 봅니다. 쏠림과 결핍이 곧 당신의 기본 설정값입니다.</p>
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(240px,1fr))',gap:16,marginBottom:14}}>
        <div style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.12)'}}>
          <p className="cin ov-label" style={{marginBottom:10}}>4원소 분포</p>
          <Bar rows={elemRows}/>
        </div>
        <div style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.12)'}}>
          <p className="cin ov-label" style={{marginBottom:10}}>3모달리티 분포</p>
          <Bar rows={modRows}/>
          <p className="ov-sub" style={{marginTop:10}}>{MODALITIES[balance.domMod].desc}</p>
        </div>
      </div>
      <div style={{display:'flex',flexDirection:'column',gap:8}}>
        <div style={{background:'rgba(201,168,76,.05)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.14)'}}>
          <p className="cin ov-label" style={{marginBottom:5}}>우세 — {ELEMENTS[balance.domElem].emoji} {ELEMENTS[balance.domElem].name} · {MODALITIES[balance.domMod].short}궁</p>
          <p className="ov-body">{ELEMENT_BALANCE_READING[balance.domElem].dom} {MODALITY_BALANCE_READING[balance.domMod].dom}</p>
        </div>
        <div style={{background:'rgba(255,255,255,.02)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.1)'}}>
          <p className="cin ov-label" style={{marginBottom:5}}>보완 — {ELEMENTS[balance.lackElem].emoji} {ELEMENTS[balance.lackElem].name} · {MODALITIES[balance.lackMod].short}궁</p>
          <p className="ov-body">{ELEMENT_BALANCE_READING[balance.lackElem].lack} {MODALITY_BALANCE_READING[balance.lackMod].lack}</p>
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   행성 어스펙트 (전문 섹션 — 실계산 시에만 노출)
════════════════════════════════════════════════════════ */
function AspectSection({aspects}){
  if(!Array.isArray(aspects)||aspects.length===0) return null;
  return(
    <div className="scard gb">
      <SectionHead icon="📐" kicker="MAJOR ASPECTS" title="행성 어스펙트"/>
      <p className="ov-sub" style={{marginBottom:14}}>실측 황경으로 계산한 행성 간 각도입니다. 오브(오차)가 작을수록 그 조합의 주제가 인생에서 강하게 작동합니다.</p>
      <div style={{display:'flex',flexDirection:'column',gap:8}}>
        {aspects.map((a,i)=>(
          <div key={i} style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'13px 15px',border:'1px solid rgba(201,168,76,.13)'}}>
            <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:6,flexWrap:'wrap'}}>
              <span className="ov-card-title" style={{fontSize:16}}>
                {PLANET_LABELS[a.a].emoji} {PLANET_LABELS[a.a].ko} <span style={{color:'#C9A84C'}}>{a.def.sym}</span> {PLANET_LABELS[a.b].emoji} {PLANET_LABELS[a.b].ko}
              </span>
              <span style={{fontSize:11.5,color:'rgba(201,168,76,.85)',background:'rgba(201,168,76,.07)',border:'1px solid rgba(201,168,76,.2)',borderRadius:20,padding:'3px 10px'}}>{a.def.name} {a.def.angle}° · 오브 {a.orb}°</span>
            </div>
            {a.theme&&<p style={{fontSize:13,color:'#F5DC70',marginBottom:5,lineHeight:1.6}}>{a.theme}</p>}
            <p className="ov-body">{a.def.quality}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

function PremiumOracleSection({result}){
  const premium = result.premium;
  const [insightTab,setInsightTab] = useState('sun');
  const [openPlace,setOpenPlace] = useState(null);
  if (!premium) return null;

  const insightMap = {
    sun:{label:'태양궁 해석',icon:'☀️',items:premium.sunInterpretation},
    moon:{label:'달궁 해석',icon:'🌙',items:premium.moonInterpretation},
    rising:{label:'상승궁 해석',icon:'⬆️',items:premium.risingInterpretation},
    synthesis:{label:'태양·달·상승 통합',icon:'🧭',items:premium.synthesis},
  };
  const activeInsight = insightMap[insightTab];

  return(
    <div className="scard gb">
      <SectionHead icon="⚡" kicker="PREMIUM DOSSIER" title="올림푸스 신탁 확장 리포트"/>

      <div style={{background:'rgba(201,168,76,.05)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.14)',marginBottom:12}}>
        <p className="cin ov-label" style={{marginBottom:8}}>핵심 요약</p>
        {premium.summary.map((p,i)=>(
          <p key={i} className="ov-body" style={{marginBottom:i<premium.summary.length-1?10:0}}>{p}</p>
        ))}
      </div>

      <div style={{display:'flex',gap:6,marginBottom:12,flexWrap:'wrap'}}>
        {['sun','moon','rising','synthesis'].map((k)=>(
          <button key={k} className={`btn-tab${insightTab===k?' act':''}`} onClick={()=>setInsightTab(k)} aria-label={`${insightMap[k].label} 보기`} style={{flex:'1 1 120px'}}>
            {insightMap[k].icon} {insightMap[k].label}
          </button>
        ))}
      </div>

      <div style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.12)',marginBottom:16}}>
        <p className="cin ov-label" style={{marginBottom:8}}>{activeInsight.icon} {activeInsight.label}</p>
        {activeInsight.items.map((p,i)=>(
          <p key={i} className="ov-body" style={{marginBottom:i<activeInsight.items.length-1?10:0}}>{p}</p>
        ))}
      </div>

      <div style={{marginBottom:16}}>
        <h4 className="ov-sec-title" style={{fontSize:'clamp(18px,2.3vw,21px)',marginBottom:4}}>추천 장소 10선</h4>
        <p className="ov-sub" style={{marginBottom:12}}>당신의 태양·달·상승궁 원소와 결이 맞는 공간을 골랐습니다. 운은 장소의 결을 따라 흐릅니다.</p>
        <div style={{display:'flex',flexDirection:'column',gap:10}}>
          {premium.places.map((pl,i)=>{
            const avoid=pl.category==='피해야 할 장소';
            return(
              <div key={i} style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'14px 16px',border:`1px solid ${avoid?'rgba(220,20,60,.25)':'rgba(201,168,76,.13)'}`}}>
                <span style={{display:'inline-block',fontSize:11.5,color:avoid?'rgba(255,120,140,.9)':'rgba(201,168,76,.85)',background:avoid?'rgba(220,20,60,.08)':'rgba(201,168,76,.07)',border:`1px solid ${avoid?'rgba(220,20,60,.25)':'rgba(201,168,76,.2)'}`,borderRadius:20,padding:'3px 10px',marginBottom:8}}>{avoid?'⚠️ ':''}{pl.category}</span>
                <div style={{display:'flex',justifyContent:'space-between',gap:10,alignItems:'flex-start'}}>
                  <p className="ov-card-title">{pl.name}</p>
                  <button className="btn-o" onClick={()=>setOpenPlace(openPlace===i?null:i)} aria-label={`${pl.name} 상세 정보 ${openPlace===i?'접기':'펼치기'}`} aria-expanded={openPlace===i} style={{padding:'8px 14px',fontSize:12,whiteSpace:'nowrap',flexShrink:0}}>{openPlace===i?'접기':'상세'}</button>
                </div>
                <p className="ov-body" style={{marginTop:6}}>{pl.reason}</p>
                {openPlace===i&&(
                  <div className="fi" style={{marginTop:10,paddingTop:10,borderTop:'1px solid rgba(201,168,76,.15)',display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(220px,1fr))',gap:'8px 16px'}}>
                    {[["좋은 행동",pl.actions],["열어주는 운",pl.luckOpen],["피해야 할 시간대",pl.avoidTime],["주의할 점",pl.caution]].map(([l,v])=>(
                      <div key={l}>
                        <p className="cin ov-label" style={{marginBottom:3}}>{l}</p>
                        <p style={{fontSize:13.5,color:'rgba(239,228,192,.82)',lineHeight:1.7}}>{v}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div style={{background:'rgba(12,8,2,.7)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.15)'}}>
        <p className="cin ov-label" style={{marginBottom:8}}>최종 신탁 문장</p>
        {premium.finalOracles.map((line,i)=>(
          <p key={i} className="ov-body" style={{marginBottom:i<premium.finalOracles.length-1?8:0}}>{i+1}. {line}</p>
        ))}
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   SECTION 3 — 타짜: 인생 베팅 스타일
════════════════════════════════════════════════════════ */
/* ════════════════════════════════════════════════════════
   FAKBOK SECTION — 확장 팩폭 주의보
════════════════════════════════════════════════════════ */
function FakbokSection({fakbok,result}){
  const [activeTab,setActiveTab]=useState('sun');
  const [expandedIdx,setExpandedIdx]=useState(null);
  const tabs=[{k:'sun',e:'☀️',l:'태양자리',sub:'핵심 본질'},{k:'moon',e:'🌙',l:'달자리',sub:'숨겨진 속'},{k:'rising',e:'⬆️',l:'상승궁',sub:'보이는 나'}];
  const activeItems=fakbok[activeTab]||[];
  const tabColors={sun:'rgba(240,180,30,.7)',moon:'rgba(80,120,200,.7)',rising:'rgba(90,180,160,.7)'};
  const borderColors={sun:'rgba(240,180,30,.3)',moon:'rgba(80,120,200,.3)',rising:'rgba(90,180,160,.3)'};
  return(
    <div className="scard gb">
      <SectionHead icon="⚠️" kicker="SECTION 1" title="팩폭 주의보"/>
      {/* 별자리 타이틀 */}
      <div style={{background:'rgba(201,168,76,.06)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.15)',marginBottom:12,textAlign:'center'}}>
        <p style={{fontSize:14,color:'#F5DC70',fontWeight:600,lineHeight:1.6}}>{fakbok.title}</p>
      </div>
      {/* 행성 탭 */}
      <div style={{display:'flex',gap:5,marginBottom:12}}>
        {tabs.map(t=>(
          <button key={t.k} onClick={()=>{setActiveTab(t.k);setExpandedIdx(null);}} className={`btn-tab${activeTab===t.k?' act':''}`} style={{flex:1,padding:'8px 4px'}}>
            <div style={{fontSize:14,marginBottom:2}}>{t.e}</div>
            <div style={{fontSize:9}}>{t.l}</div>
          </button>
        ))}
      </div>
      {/* 현재 탭 행성 위치 */}
      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:12,background:'rgba(255,255,255,.02)',borderRadius:8,padding:'8px 12px',border:`1px solid ${borderColors[activeTab]}`}}>
        <span style={{fontSize:18}}>{tabs.find(t=>t.k===activeTab).e}</span>
        <div>
          <p style={{fontSize:9,color:tabColors[activeTab],marginBottom:2}}>{tabs.find(t=>t.k===activeTab).l} 위치</p>
          <p style={{fontSize:13,fontWeight:600,color:'#F0D060'}}>
            {activeTab==='sun'?`${result.sun.name} ${result.sun.sym}`:
             activeTab==='moon'?`${result.moon.name} ${result.moon.sym}`:
             `${result.rising.name} ${result.rising.sym}`}
          </p>
        </div>
        <div style={{marginLeft:'auto',textAlign:'right'}}>
          <p style={{fontSize:9,color:'rgba(239,228,192,.35)'}}>수호신</p>
          <p style={{fontSize:11,color:'rgba(201,168,76,.7)'}}>
            {activeTab==='sun'?result.sun.god:activeTab==='moon'?result.moon.god:result.rising.god}
          </p>
        </div>
      </div>
      {/* 항목 아코디언 */}
      <div style={{display:'flex',flexDirection:'column',gap:7}}>
        {activeItems.map((item,i)=>(
          <div key={`${activeTab}-${i}`} onClick={()=>setExpandedIdx(expandedIdx===i?null:i)}
            role="button" tabIndex={0} aria-expanded={expandedIdx===i}
            onKeyDown={(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setExpandedIdx(expandedIdx===i?null:i);}}}
            style={{background:expandedIdx===i?'rgba(255,255,255,.035)':'rgba(255,255,255,.02)',borderRadius:10,padding:'13px 15px',cursor:'pointer',transition:'all .25s',border:`1px solid ${expandedIdx===i?borderColors[activeTab]:'rgba(201,168,76,.12)'}`}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8}}>
              <p style={{fontSize:13.5,color:expandedIdx===i?tabColors[activeTab]:'#C9A84C',fontWeight:600,lineHeight:1.5}}>{item.label}</p>
              <span aria-hidden="true" style={{fontSize:11,color:'rgba(239,228,192,.35)',transform:expandedIdx===i?'rotate(180deg)':'none',transition:'transform .2s',flexShrink:0}}>▼</span>
            </div>
            {expandedIdx===i&&(
              <p className="fi ov-body" style={{marginTop:10}}>{item.text}</p>
            )}
          </div>
        ))}
      </div>
      {/* 조합 분석 + 트리거 */}
      <div style={{marginTop:12,display:'flex',flexDirection:'column',gap:7}}>
        <div style={{background:'rgba(240,180,30,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(240,180,30,.15)'}}>
          <p style={{fontSize:13,fontWeight:600,color:'rgba(240,180,30,.85)',marginBottom:5}}>🔮 행성 조합 분석</p>
          <p className="ov-body">{fakbok.combo}</p>
        </div>
        <div style={{background:'rgba(220,20,60,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(220,20,60,.18)'}}>
          <p style={{fontSize:13,fontWeight:600,color:'rgba(220,20,60,.85)',marginBottom:5}}>💣 본성 폭발 트리거</p>
          <p className="ov-body">{fakbok.trigger}</p>
        </div>
      </div>
    </div>
  );
}

function TazzaSection({data,marsSign,jupSign,satSign,guide}){
  const {style,luck,trap}=data;
  const [showOdds,setShowOdds]=useState(false);
  const [openGuide,setOpenGuide]=useState(null);
  useEffect(()=>{const t=setTimeout(()=>setShowOdds(true),400);return()=>clearTimeout(t);},[]);
  const cards=['🀇','🀈','🀉','🀊','🀋'];
  return(
    <div className="scard tazza-bg">
      <SectionHead icon="🃏" kicker="SECTION 3" title="타짜: 인생 베팅 가이드" tone="crimson"/>
      {/* 패 테이블 */}
      <div className="tazza-felt" style={{borderRadius:10,padding:'14px 12px',border:'1px solid rgba(0,80,0,.4)',marginBottom:14}}>
        <div style={{display:'flex',justifyContent:'center',gap:8,marginBottom:12}}>
          {cards.map((c,i)=>(
            <div key={i} className={`card-flip ${i%2===0?'card-red':'card-dark'}`} style={{animationDelay:`${i*.15}s`}}>
              <span style={{fontSize:16}}>{[style.card,'🃏','🀄','🎴','♠️'][i]}</span>
            </div>
          ))}
        </div>
        <div style={{textAlign:'center'}}>
          <p className="cin" style={{fontSize:11,color:'rgba(220,20,60,.7)',letterSpacing:3,marginBottom:5}}>MARS — {marsSign.name}</p>
          <p className="cin" style={{fontSize:19,color:'#DC143C',fontWeight:700,marginBottom:8}}>{style.title}</p>
          <p style={{fontSize:13.5,color:'rgba(239,228,192,.75)',lineHeight:1.85,fontStyle:'italic'}}>"{style.dialogue}"</p>
        </div>
      </div>
      {/* 오늘의 배당률 */}
      <div style={{background:'rgba(0,0,0,.6)',borderRadius:10,padding:14,border:'1px solid rgba(220,20,60,.25)',marginBottom:12}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
          <p className="cin" style={{fontSize:9,color:'rgba(220,20,60,.7)',letterSpacing:2}}>오늘의 행운 배당률</p>
          <p className="mono" style={{fontSize:22,color:'#DC143C',fontWeight:700}}>{style.odds}%</p>
        </div>
        <div style={{background:'rgba(255,255,255,.05)',borderRadius:4,height:8,overflow:'hidden',marginBottom:8}}>
          <div style={{height:'100%',width:showOdds?`${style.odds}%`:'0%',borderRadius:4,background:'linear-gradient(90deg,#4a0000,#8B0000,#DC143C)',transition:'width 1.5s cubic-bezier(.34,1.2,.64,1)'}}/>
        </div>
        <div style={{display:'flex',justifyContent:'space-between'}}>
          <span style={{fontSize:10,color:'rgba(220,20,60,.5)'}}>FOLD</span>
          <span style={{fontSize:10,color:'rgba(220,20,60,.5)'}}>ALL-IN</span>
        </div>
      </div>
      {/* 목성 운빨 / 토성 함정 */}
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
        <div style={{background:'rgba(255,215,0,.05)',borderRadius:8,padding:11,border:'1px solid rgba(255,215,0,.2)'}}>
          <p className="cin" style={{fontSize:8,color:'rgba(255,215,0,.7)',letterSpacing:2,marginBottom:6}}>⚡ 목성 운빨 — {jupSign.name}</p>
          <div style={{textAlign:'center',marginBottom:6}}>
            <p className="mono" style={{fontSize:20,color:'#FFD700'}}>{luck.lv}%</p>
            <p style={{fontSize:9,color:'rgba(255,215,0,.5)'}}>LUCK INDEX</p>
          </div>
          <p style={{fontSize:13,color:'rgba(239,228,192,.72)',lineHeight:1.75}}>{luck.txt}</p>
        </div>
        <div style={{background:'rgba(80,0,0,.4)',borderRadius:8,padding:11,border:'1px solid rgba(180,0,0,.3)'}}>
          <p className="cin" style={{fontSize:8,color:'rgba(220,20,60,.7)',letterSpacing:2,marginBottom:6}}>⚠️ 토성 함정 — {satSign.name}</p>
          <div style={{textAlign:'center',marginBottom:6}}>
            <p className="cin" style={{fontSize:14,color:'#DC143C',fontWeight:700}}>{trap.trap}</p>
            <p style={{fontSize:9,color:'rgba(220,20,60,.5)'}}>WEAKNESS</p>
          </div>
          <p style={{fontSize:13,color:'rgba(239,228,192,.72)',lineHeight:1.75}}>{trap.txt}</p>
        </div>
      </div>
      <div style={{marginTop:12,background:'rgba(0,0,0,.4)',borderRadius:8,padding:'8px 12px',border:'1px solid rgba(220,20,60,.15)'}}>
        <p style={{fontSize:10,color:'rgba(220,20,60,.5)',textAlign:'center'}}>오늘의 베팅 칩: <span style={{color:'#DC143C',fontWeight:700}}>{style.chip}</span> — 도박은 올림포스 신들도 말립니다</p>
      </div>

      {Array.isArray(guide) && guide.length>0 && (
        <div style={{marginTop:10,display:'flex',flexDirection:'column',gap:7}}>
          {guide.map((item,i)=>(
            <div key={i} style={{background:'rgba(255,255,255,.02)',borderRadius:8,padding:'10px 12px',border:'1px solid rgba(220,20,60,.2)'}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8}}>
                <p style={{fontSize:14.5,color:'#DC143C',fontWeight:700,lineHeight:1.5}}>{item.title}</p>
                <button className="btn-o" onClick={()=>setOpenGuide(openGuide===i?null:i)} aria-label={`${item.title} ${openGuide===i?'접기':'펼치기'}`} aria-expanded={openGuide===i} style={{padding:'8px 13px',fontSize:12,borderColor:'rgba(220,20,60,.45)',color:'#DC143C',flexShrink:0}}>{openGuide===i?'접기':'보기'}</button>
              </div>
              {openGuide===i&&(
                <div className="fi" style={{marginTop:10,paddingTop:10,borderTop:'1px solid rgba(220,20,60,.2)'}}>
                  {item.paragraphs.map((txt,pIdx)=>(
                    <p key={pIdx} className="ov-body" style={{marginBottom:pIdx<item.paragraphs.length-1?8:0}}>{txt}</p>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   SECTION 4 — 악마 계약서
════════════════════════════════════════════════════════ */
function DevilSection({devil,rising,mercury}){
  const [signed,setSigned]=useState(false);
  const [confirming,setConfirming]=useState(false);
  const drips=Array.from({length:6},(_,i)=>i);
  return(
    <div className="scard blood-bg">
      <SectionHead icon="👹" kicker="SECTION 4" title="행성과의 위험한 계약서" tone="crimson"/>
      {/* 피 방울 — transform-only animation, no reflow */}
      <div style={{display:'flex',gap:16,justifyContent:'center',marginBottom:14,height:22,alignItems:'flex-start',overflow:'hidden'}}>
        {drips.map(i=><div key={i} className="blood-drip" style={{animationDelay:`${i*.4}s`}}/>)}
      </div>
      {/* 봉인 */}
      <div style={{display:'flex',justifyContent:'center',marginBottom:16}}>
        <div className="blood-seal" style={{width:80,height:80,background:'radial-gradient(circle,rgba(60,0,0,.9),rgba(20,0,0,.95))',border:'1px solid rgba(220,20,60,.4)'}}>
          <span style={{fontSize:34}}>{devil.sigil}</span>
        </div>
      </div>
      <div style={{textAlign:'center',marginBottom:14}}>
        <p className="cin" style={{fontSize:9,color:'rgba(180,0,0,.6)',letterSpacing:3,marginBottom:4}}>계약 당사자: {rising.name} 상승궁</p>
        <p className="cin" style={{fontSize:16,color:'#DC143C',fontWeight:700,marginBottom:4}}>{devil.name}</p>
        <p style={{fontSize:10,color:'rgba(220,20,60,.5)'}}>{devil.contract}</p>
      </div>
      {/* 계약서 본문 */}
      <div style={{background:'rgba(10,0,0,.8)',borderRadius:10,padding:16,border:'1px solid rgba(180,0,0,.3)'}}>
        <p className="cin" style={{fontSize:8,color:'rgba(180,0,0,.5)',letterSpacing:4,marginBottom:12,textAlign:'center'}}>✦ PACTUM DIABOLI ✦</p>
        <div className="contract-line">
          <p className="cin" style={{fontSize:12,color:'rgba(220,20,60,.8)',fontWeight:600,marginBottom:6,letterSpacing:1}}>제1조 — 부여된 능력</p>
          <p className="ov-body">{devil.power}</p>
        </div>
        <div style={{marginBottom:12}}>
          <p className="cin" style={{fontSize:12,color:'rgba(220,20,60,.8)',fontWeight:600,marginBottom:6,letterSpacing:1}}>제2조 — 계약의 대가</p>
          <p className="ov-body" style={{fontStyle:'italic'}}>"{devil.price}"</p>
        </div>
        <div style={{background:'rgba(180,0,0,.08)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(180,0,0,.2)',marginBottom:12}}>
          <p className="cin" style={{fontSize:12,color:'rgba(220,20,60,.7)',fontWeight:600,letterSpacing:1,marginBottom:5}}>수성({mercury.name}) 특약</p>
          <p style={{fontSize:13.5,color:'rgba(239,228,192,.72)',lineHeight:1.8}}>{mercury.pd.t}</p>
        </div>
        {/* 서명 */}
        <div style={{borderTop:'1px solid rgba(180,0,0,.3)',paddingTop:14,textAlign:'center'}}>
          {!confirming && !signed && (
            <button onClick={()=>setConfirming(true)} className="btn-o" style={{borderColor:'rgba(220,20,60,.5)',color:'#DC143C',width:'100%',padding:'11px',fontSize:11}}>
              피로 서명하기 (취소 불가)
            </button>
          )}
          {confirming && !signed && (
            <div className="fi" style={{background:'rgba(80,0,0,.4)',borderRadius:10,padding:16,border:'1px solid rgba(220,20,60,.4)'}}>
              <p style={{fontSize:16,marginBottom:10}}>⚠️</p>
              <p className="cin" style={{fontSize:11,color:'#DC143C',letterSpacing:1,marginBottom:8,lineHeight:1.6}}>최후의 경고</p>
              <p style={{fontSize:12,color:'rgba(239,228,192,.75)',lineHeight:1.9,marginBottom:14}}>
                이 계약은 <span style={{color:'#DC143C',fontWeight:600}}>올림포스 영구 기록</span>에 남습니다.<br/>
                서명 즉시 능력을 얻는 대신<br/>
                <span style={{color:'rgba(220,20,60,.9)',fontStyle:'italic'}}>"{devil.price}"</span><br/>
                이 저주는 <span style={{color:'#DC143C',fontWeight:600}}>취소·환불·반품 불가</span>입니다.<br/>
                그래도 서명하시겠습니까?
              </p>
              <div style={{display:'flex',gap:8}}>
                <button onClick={()=>setConfirming(false)} className="btn-o" style={{flex:1,padding:'10px',fontSize:11}}>
                  도망가기
                </button>
                <button onClick={()=>{setSigned(true);setConfirming(false);}} className="btn-o" style={{flex:1,padding:'10px',fontSize:11,borderColor:'rgba(220,20,60,.6)',color:'#DC143C'}}>
                  영혼으로 서명
                </button>
              </div>
            </div>
          )}
          {signed && (
            <div className="fi">
              <p className="cin" style={{fontSize:9,color:'rgba(220,20,60,.6)',letterSpacing:3,marginBottom:6}}>계약 완료 — 되돌릴 수 없습니다</p>
              <p className="mono" style={{fontSize:13,color:'#DC143C',letterSpacing:2}}>✍️ 영혼으로 서명됨</p>
              <p style={{fontSize:10,color:'rgba(180,0,0,.5)',marginTop:4}}>이 계약은 올림포스에 영구 보관됩니다</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   SECTION 5 — K-직장인 오피스 (매일 시나리오 변경)
════════════════════════════════════════════════════════ */
function OfficeSection({office,sunName,mercName}){
  const today=new Date();
  // 오늘 날짜 기준으로 일별 시나리오 인덱스 결정
  const dayOfYear=Math.floor((today-(new Date(today.getFullYear(),0,0)))/86400000);
  const scenIdx=dayOfYear%office.scenarios.length;
  const scene=office.scenarios[scenIdx];
  const tipIdx=today.getDay(); // 0=일,1=월,...6=토
  const tip=office.dailyTips[tipIdx];
  const dayLabels=["일요일","월요일","화요일","수요일","목요일","금요일","토요일"];
  const [chatReplyIdx,setChatReplyIdx]=useState(0);
  const [showAllTips,setShowAllTips]=useState(false);
  const villainColor=(v)=>v>=70?'#E85D1B':v>=50?'#C9A84C':'#7AB540';
  const quitColor=(v)=>v>=70?'#DC143C':v>=50?'#C9A84C':'#4A8FD4';
  return(
    <div className="scard gb">
      <SectionHead icon="🏢" kicker="SECTION 5" title="올림포스 오피스 생존기"/>

      {/* 직급 배지 */}
      <div style={{background:'rgba(201,168,76,.06)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.18)',marginBottom:12}}>
        <div style={{display:'flex',alignItems:'center',gap:10}}>
          <div style={{width:46,height:46,borderRadius:10,background:'rgba(201,168,76,.12)',border:'1px solid rgba(201,168,76,.3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:22}}>
            {office.rank.split(' ')[0]}
          </div>
          <div>
            <p className="cin" style={{fontSize:9,color:'rgba(201,168,76,.55)',letterSpacing:2,marginBottom:3}}>SUN — {sunName}</p>
            <p style={{fontSize:14,color:'#F5DC70',fontWeight:600}}>{office.rank.substring(office.rank.indexOf(' ')+1)}</p>
            <p style={{fontSize:10,color:'rgba(239,228,192,.4)',marginTop:2}}>수성({mercName}) 메신저 말투</p>
          </div>
        </div>
      </div>

      {/* 게이지 바 */}
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:10,marginBottom:14}}>
        {[{l:"빌런 지수",v:office.villain,c:villainColor(office.villain)},{l:"탈출(퇴사) 지수",v:office.quit,c:quitColor(office.quit)}].map((g,i)=>(
          <div key={i} style={{background:'rgba(255,255,255,.03)',borderRadius:8,padding:10,border:'1px solid rgba(201,168,76,.1)'}}>
            <div style={{display:'flex',justifyContent:'space-between',marginBottom:6}}>
              <p style={{fontSize:10,color:'rgba(239,228,192,.5)'}}>{g.l}</p>
              <p className="mono" style={{fontSize:13,color:g.c,fontWeight:700}}>{g.v}%</p>
            </div>
            <div className="gauge-bar"><div className="gauge-fill" style={{width:`${g.v}%`,background:`linear-gradient(90deg,${g.c}60,${g.c})`}}/></div>
          </div>
        ))}
      </div>

      {/* 오늘의 상황 시나리오 */}
      <div style={{background:'rgba(255,255,255,.02)',borderRadius:10,padding:14,border:'1px solid rgba(201,168,76,.18)',marginBottom:12}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}>
          <p className="cin" style={{fontSize:9,color:'#C9A84C',letterSpacing:2}}>오늘의 오피스 시나리오</p>
          <span style={{fontSize:10,color:'rgba(201,168,76,.45)',background:'rgba(201,168,76,.07)',borderRadius:10,padding:'2px 8px',border:'1px solid rgba(201,168,76,.2)'}}>
            {today.getMonth()+1}/{today.getDate()} 에피소드 {scenIdx+1}/{office.scenarios.length}
          </span>
        </div>
        <div style={{background:'rgba(201,168,76,.06)',borderRadius:8,padding:'9px 12px',marginBottom:10,border:'1px solid rgba(201,168,76,.12)'}}>
          <p style={{fontSize:12,color:'rgba(201,168,76,.75)',marginBottom:4}}>📌 상황</p>
          <p style={{fontSize:14.5,color:'#F0D060',fontWeight:600,lineHeight:1.55}}>{scene.sit}</p>
        </div>
        <div style={{display:'flex',alignItems:'flex-start',gap:8,marginBottom:10}}>
          <div style={{width:32,height:32,borderRadius:8,background:'rgba(180,0,0,.25)',border:'1px solid rgba(220,20,60,.3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,flexShrink:0}}>👔</div>
          <div style={{flex:1}}>
            <p style={{fontSize:9,color:'rgba(220,20,60,.6)',marginBottom:4}}>{scene.bossSign}</p>
            <div className="chat-bubble-boss" style={{maxWidth:'100%',display:'inline-block'}}>
              <p style={{fontSize:13.5,color:'rgba(239,228,192,.85)',lineHeight:1.7}}>{scene.boss}</p>
            </div>
          </div>
        </div>
        {/* 내 답장 선택지 */}
        <div style={{marginBottom:10}}>
          <p style={{fontSize:9,color:'rgba(201,168,76,.5)',marginBottom:7,paddingLeft:40}}>나 ({sunName}) 의 답장 선택지:</p>
          <div style={{display:'flex',flexDirection:'column',gap:6}}>
            {scene.me.map((reply,i)=>(
              <div key={i} onClick={()=>setChatReplyIdx(i)}
                style={{display:'flex',justifyContent:'flex-end',cursor:'pointer'}}>
                <div className={chatReplyIdx===i?'chat-bubble-me':''}
                  style={{maxWidth:'85%',padding:'8px 12px',borderRadius:'14px 14px 4px 14px',background:chatReplyIdx===i?'rgba(201,168,76,.18)':'rgba(255,255,255,.03)',border:chatReplyIdx===i?'1px solid rgba(201,168,76,.35)':'1px solid rgba(255,255,255,.07)',transition:'all .2s',cursor:'pointer'}}>
                  <p style={{fontSize:13.5,color:chatReplyIdx===i?'rgba(239,228,192,.95)':'rgba(239,228,192,.5)',lineHeight:1.65}}>{reply}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
        <div style={{display:'flex',alignItems:'flex-start',gap:8}}>
          <div style={{width:32,height:32,borderRadius:8,background:'rgba(0,80,160,.25)',border:'1px solid rgba(0,120,255,.3)',display:'flex',alignItems:'center',justifyContent:'center',fontSize:14,flexShrink:0}}>👤</div>
          <div style={{flex:1}}>
            <p style={{fontSize:9,color:'rgba(100,160,255,.6)',marginBottom:4}}>{scene.colSign}</p>
            <div className="chat-bubble-boss" style={{maxWidth:'100%',display:'inline-block'}}>
              <p style={{fontSize:13.5,color:'rgba(239,228,192,.8)',lineHeight:1.7}}>{scene.colleague}</p>
            </div>
          </div>
        </div>
        <p style={{fontSize:9,color:'rgba(201,168,76,.3)',textAlign:'center',marginTop:10}}>
          답장 선택지를 탭하면 하이라이트됩니다
        </p>
      </div>

      {/* 오늘의 팁 */}
      <div style={{background:'rgba(201,168,76,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.16)',marginBottom:10}}>
        <p style={{fontSize:13,fontWeight:600,color:'#C9A84C',marginBottom:5}}>
          📅 {dayLabels[today.getDay()]} 팁
        </p>
        <p className="ov-body">{tip}</p>
      </div>

      {/* 요일별 팁 전체 보기 */}
      <button onClick={()=>setShowAllTips(!showAllTips)} className="btn-o" style={{width:'100%',padding:'8px',fontSize:10,borderColor:'rgba(201,168,76,.2)',marginBottom:showAllTips?10:0}}>
        {showAllTips?'▲ 접기':'▼ 이번 주 전체 팁 보기 (7일치)'}
      </button>
      {showAllTips&&(
        <div className="fi" style={{display:'flex',flexDirection:'column',gap:6}}>
          {office.dailyTips.map((t,i)=>(
            <div key={i} style={{background:i===today.getDay()?'rgba(201,168,76,.07)':'rgba(255,255,255,.02)',borderRadius:7,padding:'9px 12px',border:i===today.getDay()?'1px solid rgba(201,168,76,.25)':'1px solid rgba(255,255,255,.05)'}}>
              <p style={{fontSize:9,color:i===today.getDay()?'#C9A84C':'rgba(201,168,76,.4)',marginBottom:3,fontWeight:i===today.getDay()?700:400}}>{dayLabels[i]}{i===today.getDay()?' ← 오늘':''}</p>
              <p style={{fontSize:11,color:'rgba(239,228,192,.7)',lineHeight:1.8}}>{t.replace(/^[월화수목금토일]요일: /,'')}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   SECTION 6 — 아스트로 맵: 세계 여행
════════════════════════════════════════════════════════ */
function DestinySpotSection({atlas,elemKey}){
  const [selDest,setSelDest]=useState(0);
  const [selSpot,setSelSpot]=useState(null);
  const ec={fire:'#E85D1B',earth:'#7AB540',air:'#5BA3C9',water:'#4A8FD4'};
  const color=ec[elemKey];
  if(!atlas||!atlas.length) return null;
  const dest=atlas[selDest]||atlas[0];
  const pickDest=(i)=>{setSelDest(i);setSelSpot(null);};
  return(
    <div className="scard gb">
      <SectionHead icon="🧭" kicker="SECTION 6" title="운명의 좌표: 세계 여행 스팟"/>
      <p className="ov-sub" style={{marginBottom:10}}>태양·달·상승궁 원소와 맞물리는 순서로 16개국 중 8개국을 골랐습니다. 위에 있을수록 지금의 배치와 가깝습니다.</p>
      {/* 추천 목적지 탭 */}
      <div style={{display:'flex',gap:6,flexWrap:'wrap',marginBottom:12}}>
        {atlas.map((d,i)=>(
          <button key={d.code} className={`btn-tab${selDest===i?' act':''}`} onClick={()=>pickDest(i)} aria-label={`${d.country} 여행 스팟 보기`} style={{fontSize:12,padding:'7px 11px'}}>
            {d.rank===1?'👑 ':''}{d.flag} {d.country}
          </button>
        ))}
      </div>
      {/* 항공권 티켓 */}
      <div className="ticket-bg" style={{borderRadius:12,padding:0,marginBottom:12,overflow:'hidden'}}>
        <div style={{padding:'14px 16px',background:'rgba(201,168,76,.06)'}}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
            <div>
              <p className="cin" style={{fontSize:8,color:`${color}`,letterSpacing:3}}>ORIGIN</p>
              <p className="cin" style={{fontSize:22,color:'#F5DC70',fontWeight:700,letterSpacing:2}}>ICN</p>
              <p style={{fontSize:10,color:'rgba(239,228,192,.45)'}}>서울 인천</p>
            </div>
            <div style={{textAlign:'center'}}>
              <p style={{fontSize:18,color:'rgba(201,168,76,.4)',letterSpacing:4}}>✈</p>
              <p className="cin" style={{fontSize:8,color:'rgba(201,168,76,.55)',letterSpacing:2}}>MATCH {dest.matchScore}</p>
            </div>
            <div style={{textAlign:'right'}}>
              <p className="cin" style={{fontSize:8,color:`${color}`,letterSpacing:3}}>DESTINATION</p>
              <p className="cin" style={{fontSize:22,color:'#F5DC70',fontWeight:700,letterSpacing:2}}>{dest.code}</p>
              <p style={{fontSize:10,color:'rgba(239,228,192,.45)'}}>{dest.city}</p>
            </div>
          </div>
        </div>
        <div className="ticket-dash"/>
        <div style={{padding:'10px 16px',display:'flex',justifyContent:'space-between',alignItems:'center',gap:10}}>
          <div style={{display:'flex',gap:8,alignItems:'center'}}>
            <div className="ticket-hole"/>
            <div>
              <p style={{fontSize:9,color:`${color}`,marginBottom:1}}>✨ 행운 부적</p>
              <p style={{fontSize:11,color:'rgba(239,228,192,.7)'}}>{dest.talismanName}</p>
            </div>
          </div>
          <div style={{textAlign:'right'}}>
            <p style={{fontSize:9,color:'rgba(201,168,76,.5)',marginBottom:1}}>행운의 날</p>
            <p className="cin" style={{fontSize:11,color:'#C9A84C'}}>{dest.luckyDay}</p>
          </div>
        </div>
      </div>
      {/* 에너지 설명 */}
      <div style={{background:`${color}12`,borderRadius:8,padding:'10px 12px',border:`1px solid ${color}28`,marginBottom:12}}>
        <p style={{fontSize:11,color:`${color}`,marginBottom:3}}>{ELEMENTS[elemKey].emoji} {dest.vibe} · 매칭 {dest.matchScore}</p>
        <p style={{fontSize:12.5,color:'rgba(245,220,112,.85)',lineHeight:1.7,marginBottom:5}}>{dest.headline}</p>
        <p style={{fontSize:11,color:'rgba(239,228,192,.6)',lineHeight:1.7,marginBottom:5}}>{dest.matchLine}</p>
        <p style={{fontSize:11,color:'rgba(239,228,192,.6)',lineHeight:1.7}}>{dest.talismanDesc}</p>
      </div>
      {/* 스팟 카드 4개 */}
      <div style={{display:'flex',flexDirection:'column',gap:8}}>
        {dest.spots.map((spot,i)=>(
          <div key={i} className="spot-card" onClick={()=>setSelSpot(selSpot===i?null:i)}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}>
              <div style={{flex:1}}>
                <div style={{display:'flex',alignItems:'center',gap:7,marginBottom:4}}>
                  <span style={{fontSize:9,background:`${color}20`,color:color,border:`1px solid ${color}30`,borderRadius:10,padding:'2px 8px'}}>{spot.type}</span>
                </div>
                <p className="ov-card-title" style={{fontSize:15.5,marginBottom:4}}>{spot.name}</p>
                <p style={{fontSize:12.5,color:'rgba(201,168,76,.7)'}}>🎁 {spot.item}</p>
              </div>
              <div style={{textAlign:'right',marginLeft:8}}>
                <p style={{fontSize:10,color:'rgba(239,228,192,.3)',marginBottom:2}}>좌표</p>
                <p className="mono" style={{fontSize:9,color:'rgba(201,168,76,.5)'}}>{spot.lat.toFixed(2)}N</p>
                <p className="mono" style={{fontSize:9,color:'rgba(201,168,76,.5)'}}>{spot.lng.toFixed(2)}E</p>
              </div>
            </div>
            {selSpot===i&&(
              <div className="fi" style={{marginTop:10,paddingTop:10,borderTop:'1px solid rgba(201,168,76,.15)'}}>
                <p style={{fontSize:12,color:'rgba(239,228,192,.8)',lineHeight:1.85,fontStyle:'italic'}}>"{spot.desc}"</p>
                <div style={{display:'flex',justifyContent:'flex-end',marginTop:8}}>
                  <a href={`https://maps.google.com/?q=${spot.lat},${spot.lng}`} target="_blank" rel="noopener noreferrer" style={{fontSize:10,color:color,textDecoration:'none',border:`1px solid ${color}40`,borderRadius:6,padding:'4px 10px'}}>
                    Google Maps로 열기 →
                  </a>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
      <div style={{marginTop:10,padding:'8px 12px',background:'rgba(201,168,76,.04)',borderRadius:8,border:'1px solid rgba(201,168,76,.1)'}}>
        <p style={{fontSize:10,color:'rgba(201,168,76,.45)',textAlign:'center'}}>📍 스팟 탭하면 상세 설명 + 구글맵 연동</p>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   BONUS — 운명의 수레바퀴 (연애운)
════════════════════════════════════════════════════════ */
function WheelOfFortuneSection({result}){
  const [tab,setTab]=useState('venus');
  const [transitVenus,setTransitVenus]=useState(null);
  useEffect(()=>{
    let alive=true;
    const now=new Date();
    const payload={year:now.getFullYear(),month:now.getMonth()+1,day:now.getDate(),hour:now.getHours(),minute:now.getMinutes(),timezone:9,lat:37.5665,lon:126.9780};
    ensureOracleCompute()
      .then((fn)=>fn(payload))
      .then((r)=>{ if(alive&&r&&r.venus&&isValidSignKey(r.venus.key)) setTransitVenus(r.venus.key); })
      .catch(()=>{});
    return()=>{alive=false;};
  },[]);
  const wheel=useMemo(()=>buildWheelOfFortune(result,transitVenus),[result,transitVenus]);
  const rose='#E8618C';
  const tabs={
    venus:{label:'끌림',icon:'💘',data:wheel.venus},
    mars:{label:'밀당',icon:'🔥',data:wheel.mars},
    moon:{label:'애착',icon:'🌙',data:wheel.moon},
    timeline:{label:'흐름',icon:'📅',data:null},
  };
  const active=tabs[tab];
  const enc=wheel.encounter;
  const lw=wheel.luckyWindow;
  return(
    <div className="scard gb">
      <SectionHead icon="🎡" kicker="BONUS" title="운명의 수레바퀴 — 연애운 정밀 판독"/>

      {/* 국면 + 게이지 */}
      <div style={{background:'rgba(232,97,140,.05)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(232,97,140,.2)',marginBottom:12}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:10,marginBottom:6}}>
          <p className="ov-card-title" style={{fontSize:16}}>{wheel.phase.icon} {wheel.phase.name}</p>
          <p className="mono" style={{fontSize:15,color:rose,fontWeight:700}}>{wheel.phase.gauge}</p>
        </div>
        <div className="gauge-bar" style={{marginBottom:8}}>
          <div className="gauge-fill" style={{width:`${wheel.phase.gauge}%`,background:`linear-gradient(90deg,${rose}55,${rose})`}}/>
        </div>
        <p style={{fontSize:13,color:'#F5DC70',fontWeight:600,lineHeight:1.7,marginBottom:6}}>"{wheel.phase.drip}"</p>
        <p className="ov-body" style={{marginBottom:8}}>{wheel.phase.advice}</p>
        <p style={{fontSize:11.5,color:'rgba(239,228,192,.55)',lineHeight:1.7}}>☽ {wheel.transitNote}</p>
      </div>

      {/* 이번 시즌 우주 흐름 (기존 신탁 문장 유지) */}
      <div style={{background:'rgba(201,168,76,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.13)',marginBottom:12}}>
        <p className="cin ov-label" style={{marginBottom:6}}>☽ 이번 시즌 우주 흐름</p>
        <p style={{fontSize:14,color:'rgba(239,228,192,.88)',lineHeight:1.9,fontStyle:'italic'}}>{result.future}</p>
      </div>

      {/* 탭 */}
      <div style={{display:'flex',gap:6,marginBottom:12,flexWrap:'wrap'}}>
        {Object.keys(tabs).map((k)=>(
          <button key={k} className={`btn-tab${tab===k?' act':''}`} onClick={()=>setTab(k)} aria-label={`${tabs[k].label} 해석 보기`} style={{flex:'1 1 100px'}}>
            {tabs[k].icon} {tabs[k].label}
          </button>
        ))}
      </div>

      <div style={{background:'rgba(255,255,255,.02)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.12)',marginBottom:14}}>
        {tab==='timeline'?(
          <div style={{display:'flex',flexDirection:'column',gap:12}}>
            {wheel.timeline.map((t)=>(
              <div key={t.label} style={{borderLeft:`2px solid ${rose}40`,paddingLeft:12}}>
                <div style={{display:'flex',alignItems:'baseline',gap:8,marginBottom:4}}>
                  <span className="cin" style={{fontSize:11,color:rose,letterSpacing:1}}>{t.label}</span>
                  <span style={{fontSize:13.5,color:'#F5DC70',fontWeight:600}}>{t.title}</span>
                </div>
                <p className="ov-body">{t.text}</p>
              </div>
            ))}
          </div>
        ):(
          <>
            <div style={{display:'flex',alignItems:'center',gap:8,flexWrap:'wrap',marginBottom:8}}>
              <span style={{fontSize:11.5,color:rose,background:'rgba(232,97,140,.08)',border:'1px solid rgba(232,97,140,.25)',borderRadius:20,padding:'3px 10px'}}>{active.data.tag}</span>
            </div>
            <p style={{fontSize:14,color:'#F5DC70',fontWeight:600,lineHeight:1.7,marginBottom:10}}>"{active.data.drip}"</p>
            {active.data.paragraphs.map((p,i)=>(
              <p key={i} className="ov-body" style={{marginBottom:i<active.data.paragraphs.length-1?10:0}}>{p}</p>
            ))}
          </>
        )}
      </div>

      {/* 이번 사이클에 들어오는 사람 */}
      <div style={{background:'rgba(232,97,140,.04)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(232,97,140,.18)',marginBottom:12}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:10,marginBottom:8}}>
          <p className="cin ov-label">🎴 이번 사이클에 들어오는 사람</p>
          <p className="mono" style={{fontSize:13,color:rose,fontWeight:700}}>궁합 {enc.compatScore}</p>
        </div>
        <p className="ov-card-title" style={{marginBottom:4}}>{enc.emoji} {enc.elemName} 계열 — {enc.compatTitle}</p>
        <p style={{fontSize:12,color:'rgba(201,168,76,.7)',marginBottom:8}}>{enc.signs}</p>
        {[["등장 경로",enc.channel],["그 사람의 연애 방식",enc.firstSignal],["관계가 흘러가는 방향",enc.love],["주의할 점",enc.caution]].map(([l,v])=>(
          <div key={l} style={{marginBottom:6}}>
            <p className="cin ov-label" style={{marginBottom:2}}>{l}</p>
            <p style={{fontSize:13,color:'rgba(239,228,192,.82)',lineHeight:1.7}}>{v}</p>
          </div>
        ))}
      </div>

      {/* 럭키 윈도우 */}
      <div style={{marginBottom:12}}>
        <p className="cin ov-label" style={{marginBottom:7}}>⏰ 나만의 럭키 윈도우</p>
        <div style={{display:'flex',flexWrap:'wrap',gap:7}}>
          {[`연락하기 좋은 요일: ${lw.day}`,`고백 타이밍: ${lw.hours}`,`기운이 오르는 달: ${lw.moonPhase}`,`피할 요일: ${lw.avoidDay}`].map((t,i)=>(
            <div key={i} style={{fontSize:12,color:'rgba(201,168,76,.8)',background:'rgba(201,168,76,.05)',border:'1px solid rgba(201,168,76,.16)',borderRadius:20,padding:'5px 12px'}}>{t}</div>
          ))}
        </div>
      </div>

      {/* 그린라이트 / 레드플래그 */}
      <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(230px,1fr))',gap:10,marginBottom:12}}>
        <div style={{background:'rgba(122,181,64,.05)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(122,181,64,.22)'}}>
          <p style={{fontSize:12.5,color:'#7AB540',fontWeight:600,marginBottom:7}}>🟢 그린라이트</p>
          {wheel.greenLights.map((g,i)=>(
            <p key={i} style={{fontSize:12.5,color:'rgba(239,228,192,.8)',lineHeight:1.7,marginBottom:i<wheel.greenLights.length-1?6:0}}>· {g}</p>
          ))}
        </div>
        <div style={{background:'rgba(220,20,60,.05)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(220,20,60,.22)'}}>
          <p style={{fontSize:12.5,color:'rgba(255,120,140,.95)',fontWeight:600,marginBottom:7}}>🚩 레드플래그</p>
          {wheel.redFlags.map((r,i)=>(
            <p key={i} style={{fontSize:12.5,color:'rgba(239,228,192,.8)',lineHeight:1.7,marginBottom:i<wheel.redFlags.length-1?6:0}}>· {r}</p>
          ))}
        </div>
      </div>

      {/* 최종 판결 */}
      <div style={{background:'rgba(12,8,2,.7)',borderRadius:12,padding:'14px 16px',border:'1px solid rgba(201,168,76,.15)'}}>
        <p className="cin ov-label" style={{marginBottom:7}}>🎡 수레바퀴의 최종 판결</p>
        <p style={{fontSize:14,color:'rgba(239,228,192,.9)',lineHeight:1.9,fontStyle:'italic'}}>{wheel.verdict}</p>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   COMPAT TAB
════════════════════════════════════════════════════════ */
function CompatTab({myResult}){
  const [pName,setPName]=useState('');
  const [pDate,setPDate]=useState('');
  const [pTime,setPTime]=useState('');
  const [res,setRes]=useState(null);
  const [err,setErr]=useState('');
  const analyze=()=>{
    if(!pDate){setErr('상대방 생년월일을 입력해주세요');return;}setErr('');
    const pr=calcPlacements(pDate,pTime,pName||'상대방');
    setRes({pr,compat:getCompat(myResult.elemKey,pr.elemKey)});
  };
  const ec={fire:'#E85D1B',earth:'#7AB540',air:'#5BA3C9',water:'#4A8FD4'};
  if(res) return <CompatResult myResult={myResult} pResult={res.pr} compat={res.compat} onReset={()=>setRes(null)} ec={ec}/>;
  return(
    <div>
      <div className="scard gb" style={{marginBottom:12}}>
        <p className="cin ov-label" style={{marginBottom:12}}>나의 배치</p>
        <div style={{display:'flex',alignItems:'center',gap:10}}>
          <div className="compat-ring" style={{width:50,height:50,background:myResult.element.dark,border:`2px solid ${ec[myResult.elemKey]}38`,margin:'0 auto'}}>
            <span style={{fontSize:20}}>{myResult.sun.sym}</span>
          </div>
          <div>
            <p style={{fontSize:13,fontWeight:600,color:'#F0D060'}}>{myResult.name}</p>
            <p style={{fontSize:11,color:'rgba(201,168,76,.75)'}}>{myResult.sun.name} {myResult.element.emoji}</p>
          </div>
        </div>
      </div>
      <div className="scard gbs">
        <p className="cin ov-label" style={{marginBottom:12}}>상대방 정보</p>
        <div style={{display:'flex',flexDirection:'column',gap:12}}>
          <div>
            <label className="cin" style={{fontSize:9,color:'rgba(201,168,76,.6)',letterSpacing:2,display:'block',marginBottom:5}}>이름 (선택)</label>
            <input className="inp" type="text" value={pName} onChange={e=>setPName(e.target.value)} placeholder="상대방 이름"/>
          </div>
          <div>
            <label className="cin" style={{fontSize:9,color:'rgba(201,168,76,.6)',letterSpacing:2,display:'block',marginBottom:5}}>생년월일 *</label>
            <input className="inp" type="date" value={pDate} onChange={e=>setPDate(e.target.value)} max="2010-12-31" min="1920-01-01"/>
          </div>
          <div>
            <label className="cin" style={{fontSize:9,color:'rgba(201,168,76,.6)',letterSpacing:2,display:'block',marginBottom:5}}>태어난 시간 (선택)</label>
            <input type="time" value={pTime} onChange={e=>setPTime(e.target.value)} style={{background:'rgba(255,255,255,.04)',border:'1px solid rgba(201,168,76,.3)',borderRadius:8,padding:'11px 14px',color:'#EFE4C0',fontSize:14,width:'100%',outline:'none',colorScheme:'dark',WebkitAppearance:'auto',appearance:'auto',transition:'border-color .3s'}}/>
            <p style={{fontSize:10,color:'rgba(239,228,192,.2)',marginTop:5}}>입력 시 상승궁 정밀도 상승</p>
          </div>
        </div>
        {err&&<p style={{color:'#E85D1B',fontSize:11,marginTop:8,textAlign:'center'}}>{err}</p>}
        <div style={{marginTop:14}}><button className="btn-g" onClick={analyze}>궁합 분석하기</button></div>
      </div>
    </div>
  );
}

function CompatResult({myResult,pResult,compat,onReset,ec}){
  const bars=[
    {label:"태양자리 케미",my:myResult.sun.name,p:pResult.sun.name,score:myResult.elemKey===pResult.elemKey?85:compat.score},
    {label:"달자리 감정 싱크",my:myResult.moon.name,p:pResult.moon.name,score:myResult.moon.elem===pResult.moon.elem?88:65},
    {label:"금성 연애 스타일",my:myResult.venus.name,p:pResult.venus.name,score:myResult.venus.elem===pResult.venus.elem?82:58},
    {label:"화성 에너지",my:myResult.mars.name,p:pResult.mars.name,score:myResult.mars.elem===pResult.mars.elem?70:72},
  ];
  const bc=(s)=>s>=80?'linear-gradient(90deg,#2A8B00,#7AB540,#C5E880)':s>=65?'linear-gradient(90deg,#8B4500,#C9A84C,#F5DC70)':'linear-gradient(90deg,#6B0000,#C93030,#FF8080)';
  return(
    <div className="fi">
      <div style={{display:'flex',alignItems:'center',justifyContent:'center',gap:10,marginBottom:14}}>
        <div style={{textAlign:'center',flex:1}}>
          <div className="compat-ring" style={{width:50,height:50,background:myResult.element.dark,border:`2px solid ${ec[myResult.elemKey]}38`,margin:'0 auto 5px'}}><span style={{fontSize:20}}>{myResult.sun.sym}</span></div>
          <p style={{fontSize:11,fontWeight:600,color:'#F0D060'}}>{myResult.name}</p>
          <p style={{fontSize:10,color:'rgba(201,168,76,.65)'}}>{myResult.sun.name}</p>
        </div>
        <div style={{textAlign:'center',padding:'0 6px'}}>
          <div style={{fontSize:20,color:'#C9A84C',marginBottom:3}}>⚡</div>
          <div className="scard" style={{padding:'5px 10px',margin:0}}>
            <p className="cin" style={{fontSize:16,color:'#F5DC70',fontWeight:700}}>{compat.score}%</p>
          </div>
        </div>
        <div style={{textAlign:'center',flex:1}}>
          <div className="compat-ring" style={{width:50,height:50,background:pResult.element.dark,border:`2px solid ${ec[pResult.elemKey]}38`,margin:'0 auto 5px'}}><span style={{fontSize:20}}>{pResult.sun.sym}</span></div>
          <p style={{fontSize:11,fontWeight:600,color:'#F0D060'}}>{pResult.name}</p>
          <p style={{fontSize:10,color:'rgba(201,168,76,.65)'}}>{pResult.sun.name}</p>
        </div>
      </div>
      <div className="scard gbs oglow" style={{textAlign:'center'}}>
        <p className="cin glow2" style={{fontSize:'clamp(19px,2.6vw,23px)',marginBottom:5}}>{compat.title}</p>
        <p className="cin" style={{fontSize:12,color:'#C9A84C',letterSpacing:2,marginBottom:10}}>{compat.sub}</p>
        <Divider/>
        <p className="ov-body">{compat.detail.synergy}</p>
      </div>
      <div className="scard gb">
        <p className="cin ov-label" style={{marginBottom:12}}>행성별 케미 분석</p>
        {bars.map((b,i)=>(
          <div key={i} style={{marginBottom:i<bars.length-1?12:0}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:4}}>
              <span style={{fontSize:11,color:'rgba(239,228,192,.6)'}}>{b.label}</span>
              <div style={{display:'flex',alignItems:'center',gap:5}}>
                <span style={{fontSize:9,color:'rgba(201,168,76,.5)'}}>{b.my} × {b.p}</span>
                <span style={{fontSize:11,fontWeight:600,color:'#C9A84C'}}>{b.score}%</span>
              </div>
            </div>
            <div className="compat-bar-wrap"><div className="compat-bar" style={{width:`${b.score}%`,background:bc(b.score)}}/></div>
          </div>
        ))}
      </div>
      <div className="scard gb">
        <p className="cin ov-label" style={{marginBottom:10}}>신화적 해석</p>
        {[{i:"☀️",l:"태양자리",t:compat.detail.sun},{i:"🌙",l:"달자리",t:compat.detail.moon},{i:"💘",l:"연애 스타일",t:compat.detail.love},{i:"⚠️",l:"주의 사항",t:compat.detail.warning}].map((it,i)=>(
          <div key={i} style={{background:'rgba(201,168,76,.04)',borderRadius:10,padding:'12px 14px',border:'1px solid rgba(201,168,76,.14)',marginBottom:i<3?8:0}}>
            <p style={{fontSize:13,fontWeight:600,color:'#C9A84C',marginBottom:5}}>{it.i} {it.l}</p>
            <p className="ov-body">{it.t}</p>
          </div>
        ))}
      </div>
      <button className="btn-o" onClick={onReset} style={{width:'100%',padding:'10px'}}>다른 사람과 궁합 보기</button>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   ORACLE TAB
════════════════════════════════════════════════════════ */
function OracleTab({result}){
  const {daily,sun,element,elemKey}=result;
  const [transit,setTransit]=useState(null);
  const today=new Date(),ds=`${today.getFullYear()}년 ${today.getMonth()+1}월 ${today.getDate()}일`;
  useEffect(()=>{
    let alive=true;
    const payload={year:today.getFullYear(),month:today.getMonth()+1,day:today.getDate(),hour:today.getHours(),minute:today.getMinutes(),timezone:9,lat:37.5665,lon:126.9780};
    ensureOracleCompute()
      .then((fn)=>fn(payload))
      .then((r)=>{ if(alive&&r&&r.moon&&SIGNS.some(s=>s.key===r.moon.key)) setTransit(r); })
      .catch(()=>{});
    return()=>{alive=false;};
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[]);
  const tMoon=transit?SIGNS.find(s=>s.key===transit.moon.key):null;
  const tRelation=tMoon?elementRelation(elemKey,tMoon.elem):null;
  return(
    <div>
      <div style={{textAlign:'center',marginBottom:16}}>
        <p style={{fontSize:13,color:'rgba(201,168,76,.6)',letterSpacing:3}}>{ds}</p>
        <p className="cin ov-sub" style={{marginTop:4}}>델포이 신전의 피티아가 전합니다</p>
      </div>
      <div className="scard gb oglow">
        <SectionHead icon={daily.icon} kicker={`${daily.god}의 신탁`} title={`${sun.name}에게 전하는 오늘의 예언`}/>
        <div className="oracle-scroll scroll-reveal">
          <p className="cin ov-eyebrow" style={{letterSpacing:4,marginBottom:10,textAlign:'center'}}>✦ PROPHETIA ✦</p>
          <p style={{fontSize:15,lineHeight:2.05,color:'rgba(239,228,192,.9)',textAlign:'center',fontStyle:'italic'}}>{daily.prophecy}</p>
        </div>
        <Divider/>
        <div style={{background:'rgba(201,168,76,.05)',borderRadius:10,padding:14,border:'1px solid rgba(201,168,76,.11)'}}>
          <p className="cin ov-label" style={{marginBottom:7}}>⚡ 오늘의 지령</p>
          <p className="ov-body">{daily.action}</p>
        </div>
        <div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:8,marginTop:12}}>
          {[{l:"행운의 색",v:daily.lucky},{l:"행운의 수",v:daily.num},{l:"황금 시간",v:daily.time}].map((it,i)=>(
            <div key={i} style={{background:'rgba(255,255,255,.03)',borderRadius:10,padding:'11px 8px',textAlign:'center',border:'1px solid rgba(201,168,76,.1)'}}>
              <p style={{fontSize:11,color:'rgba(201,168,76,.6)',marginBottom:4}}>{it.l}</p>
              <p style={{fontSize:14,fontWeight:600,color:'#F0D060'}}>{it.v}</p>
            </div>
          ))}
        </div>
      </div>
      {tMoon&&(
        <div className="scard gb fi">
          <SectionHead icon="🌙" kicker="TODAY'S TRANSIT" title="오늘의 트랜짓 — 실측 달 위치"/>
          <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:10,flexWrap:'wrap'}}>
            <span className="ov-card-title">달 ☽ {tMoon.name} {tMoon.sym}{Number.isFinite(transit.moon.deg)?` · ${Math.floor(transit.moon.deg)}°`:''}</span>
            <span style={{fontSize:11.5,color:'rgba(201,168,76,.8)',background:'rgba(201,168,76,.06)',border:'1px solid rgba(201,168,76,.18)',borderRadius:20,padding:'4px 11px'}}>{ELEMENTS[tMoon.elem].emoji} {ELEMENTS[tMoon.elem].name} 통과 중</span>
          </div>
          <p className="ov-body">{TRANSIT_MOON_READING[tRelation]}</p>
        </div>
      )}
      <div className="scard gb" style={{background:element.dark}}>
        <p className="cin ov-label" style={{marginBottom:10}}>{element.faction} 원소 신탁</p>
        <p style={{fontSize:14.5,color:'rgba(239,228,192,.88)',lineHeight:2,fontStyle:'italic'}}>"{element.oracle}"</p>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════════════
   MAIN APP
════════════════════════════════════════════════════════ */
export default function OlympusVIPLounge(){
  const [screen,setScreen]=useState('intro');
  const [result,setResult]=useState(null);
  const [dailyData,setDailyData]=useState(null);
  const handleInput=({name,date,time,sunKey,placements,timeKnown})=>{
    setScreen('loading');
    const real=placements&&typeof placements==='object'?{...placements}:null;
    // 출생 시간을 모르는 프로필(정오 기본값 계산)의 상승궁은 근사치이므로 제외
    if (real&&timeKnown===false) delete real.asc;
    const minWait=new Promise((res)=>setTimeout(res,3200));
    const computed=real
      ? Promise.resolve(real)
      : (()=>{ // 직접 입력 경로: 로딩 연출 동안 Swiss 실계산 시도, 실패 시 간이 계산 폴백
          const payload=buildSwissPayload(date,time);
          if (!payload) return Promise.resolve(null);
          const timeout=new Promise((res)=>setTimeout(()=>res(null),9000));
          const calc=ensureOracleCompute()
            .then((fn)=>fn(payload))
            .then((r)=>{
              if (r&&!time) { const rest={...r}; delete rest.asc; return rest; } // 시간 미입력 → 상승궁 실계산 불가
              return r;
            })
            .catch(()=>null);
          return Promise.race([calc,timeout]);
        })();
    Promise.all([computed,minWait]).then(([realPlacements])=>{
      setResult(calcPlacements(date,time,name||'당신',sunKey,realPlacements));
      setScreen('result');
    });
  };
  useEffect(()=>{
    if (typeof window === 'undefined') return;
    try {
      const raw=sessionStorage.getItem('OLYMPUS_ORACLE_PROFILE');
      if(!raw) return;
      const payload=JSON.parse(raw);
      if(!payload||!payload.date) return;
      sessionStorage.removeItem('OLYMPUS_ORACLE_PROFILE');
      handleInput(payload);
    } catch (e) {}
  },[]);
  return(
    <div className="ov">
      <style>{CSS}</style>
      <a className="ov-home" href="/" aria-label="홈으로 이동">← 홈으로</a>
      <Cosmos/>
      {screen==='intro'        && <Intro onStart={()=>setScreen('input')} onOracle={()=>setScreen('oracle-input')}/>}
      {screen==='input'        && <Input onSubmit={handleInput} onBack={()=>setScreen('intro')}/>}
      {screen==='oracle-input' && <OracleInput onSubmit={d=>{setDailyData(d);setScreen('daily');}} onBack={()=>setScreen('intro')}/>}
      {screen==='loading'      && <Loading/>}
      {screen==='result'       && result && <TabResult result={result} onReset={()=>setScreen('intro')}/>}
      {screen==='daily'        && dailyData && <DailyOracleResult data={dailyData} onBack={()=>setScreen('oracle-input')}/>}
    </div>
  );
}
